export const artsCatalog = {"mainland":[{"id":5,"name":"Артефактология","attributes":"Искусство + Атрибут Заявки + Навыки+ Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Это основное Искусство созидательного ремесла. На низких уровнях эта магия облегчает дальнейшую работу с артефактами. На высоких уровнях это Искусство становится изменением и созиданием в полном смысле этого слова.","type":1,"first_stage_name":"Взгляд Истины","first_stage_description":"Заклинатель может узнать особые навыки и способности артефакта/материала.","second_stage_name":"Не Алхимия","second_stage_description":"Заклинатель может изменять структуру материалов, превращая один не магический расходник в другой(камень в дерево, железо в ткань…).","third_stage_name":"Модный Приговор","third_stage_description":"Это колдовство позволяет \"закалить\"(изменить) 1 свойство уже существующей магической вещи. Заклинатель не может заранее предсказать или выбрать результат изменений.","fourth_stage_name":"Самоделкин","fourth_stage_description":"Создание магических артефактов с нуля. Функциональность и внешний вид зависят от доступных ресурсов, назначения и общего уровня мастерства.","created_at":"2023-09-09T11:11:59.000000Z","updated_at":"2025-10-27T04:27:50.000000Z","deleted_at":null,"first_stage_condition":"Информацию получает только заклинатель\nТелесный контакт\nТаргетное заклинание","second_stage_condition":"Таргетное заклинание\nТелесный контакт\nНе позволяет создавать еду\nНе распространяется на драгоценные металлы и камни\nЗаклинатель должен знать свойства и качества исходного материала и изготавливаемого","third_stage_condition":"Таргетное заклинание\nТелесный контакт\nРаботает только с магическим снаряжением\nВ некоторых случаях надо \"перекинуть\" не уровень артефакта, а уровень его создателя.\nВозможен непредсказуемый эффект","fourth_stage_condition":"таргетное заклинание\nДля акта создания нужны расходные магические материалы и специальные инструменты для подобного действия.\nТелесный контакт\nВозможен непредсказуемый эффект\nНе чаще одного использования за сессию"},{"id":2,"name":"Афродезия","attributes":"Искусство + Атрибут заявки + Манипулирование + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Афродезия - это искусство соблазнения и манипуляции чужими чувствами, позволяя навязать объекту практически любые нужные вам цели.","type":1,"first_stage_name":"Любовь с первого Взгляда","first_stage_description":"Объект заклятия ощущает безоговорочную симпатию к заклинателю, даже если он до этого никогда не видел или не обращал на него внимания","second_stage_name":"Книга Души","second_stage_description":"Позволяет проникнуть в чувства объекта и узнать, что/кого он вожделеет. Успешность броска влияет на количество и качество полученной информации.","third_stage_name":"Маниакальная Фаза","third_stage_description":"Вызывает безумную кратковременную одержимость кем-либо/чем-либо. Жертва, подвергшаяся заклятию, настолько нуждается в каком-либо объекте, что готова пойти на что угодно (кроме нанесения себе непосредственного урона) ради его получения. В том числе - принести в жертву/уничтожить объект желания ради удовлетворения жажды.","fourth_stage_name":"Стокгольмский Синдром","fourth_stage_description":"Вызывает глубокую иррациональную привязанность и фанатичную одержимость выбранным заклинателем существом/объектом/местом/явлением. Побуждает объект заклятия делать всё ради получения предмета своей мании. Эффект полностью осмысленный и не проходит в течение ближайшего времени, только если заклинатель не снимет с жертвы заклятие сам (что может не получиться). Наложивший заклятье не может контролировать находящуюся в состоянии мании жертву.","created_at":"2023-09-09T10:45:37.000000Z","updated_at":"2025-10-27T04:29:27.000000Z","deleted_at":null,"first_stage_condition":"Таргетное заклинание\nОбязателен зрительный/телесный/аудио контакт с целью\nЦель должна быть разумной\nПосле спадания чар существо понимает, что его околдовали.\nВременный эффект","second_stage_condition":"Таргетное заклинание\nЗрительный/телесный/аудио контакт\nТолько на разумных существ","third_stage_condition":"Таргетное заклинание\nЗрительный/телесный/аудио контакт\nТолько на разумных существ\nПосле спадания чар существо понимает, что его околдовали\nВременный Эффект\nНе работает на другие чувства осязания, кроме разума","fourth_stage_condition":"Таргетное заклинание\nЗрительный/телесный/аудио контакт\nТолько на разумных существ\nВозможен непредсказуемый эффект\nНе чаще одного использования за сессию."},{"id":3,"name":"Изначальность","attributes":"Искусство + Атрибут заявки+ Науки+ Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Искусство взаимодействия с силами природы, общая элементальная магия.","type":1,"first_stage_name":"Посол Мира","first_stage_description":"Это колдовство позволяет говорить с чем угодно, даже с существами, которые изначально неспособны говорить или понимать человеческую речь. Число успехов определяет число задаваемых вопросов и полноту ответов, в зависимости от уровня существа/предмета/локации.","second_stage_name":"Мать Тереза (была той еще сукой)","second_stage_description":"Имеет два варианта использования: \nЖизненная сторона: Наполняет цель/цели энергией жизни и позволяет исцелить любую рану. Число успехов определяет успешность исцеления. В случае лишних успехов, заклинатель, может забрать остаток лечения себе, но не может передать его кому-то другому, если такой заявки не было изначально. Если заклинатель хочет исцелить больше одной цели, то лечение он распределяет по своему усмотрению. Лечение идет по цене 1 Успех = 1 Тупой Урон.\nСучья сторона: обращает энергию жизни в оружие против существ, в которых нет жизни. Число успехов влияет на успешность нанесения урона и количество этого урона.","third_stage_name":"Шаман-Кинг","third_stage_description":"Заклинатель, использующий это колдовство, может использовать  один из следующих природных элементов: огонь, воду, землю, воздух. Число успехов влияет на мощность эффекта используемой стихии и его длительность. Иногда может выйти из под контроля заклинателя.","fourth_stage_name":"Неведомая Хтонь","fourth_stage_description":"Это колдовство позволяет заклинателю или объекту заклинания принять любой Облик. При этом объект заклятия получает броски с помехой и преимуществом на определенные группы атрибутов, в зависимости от особенностей нового Облика. Если колдующий принимает Облик мифического зверя, то не получает его магические способности. Число успехов определяет число ходов, на протяжении которых заклинатель  использует Облик.","created_at":"2023-09-09T10:53:29.000000Z","updated_at":"2025-10-27T04:31:09.000000Z","deleted_at":null,"first_stage_condition":"Магия действует только на живых существ и то, что подходит под понятие живого внутри мира ( деревья, растения, камни и т.п.) и может иметь хотя бы самый простой разум\nТаргетное заклинание\nВременный эффект","second_stage_condition":"Жизненная сторона действует только на живых существ и то, что подходит под понятие живого внутри мира ( деревья, растения)\nНе снимает проклятия\nНе разрушает магические контракты\nНе работает с материей времени\nНе лечит магические болезни и их эффекты/симптомы\nВ приоритете всегда лечатся Увечья по цене 3 успеха = 1 Увечье.\nСучья сторона: действует только на тех существ, которые определяются как нежить.\n(так же может действовать на некоторых порождений Холодного Простора, но это индивидуально)","third_stage_condition":"Заклинатель не может создать природный элемент этим искусством\nНе может увеличить количество воды или земли\nНе работает на магически измененные элементы\nТребует поддержания колдовства.( Во время его совершения, игрок не может совершать других действий, кроме разговорных)","fourth_stage_condition":"Не дает возможности принимать облик существ инородной магической природы\nДает возможность принять облик существ относящихся к виду \"Живых\" внутри мира\nНе передает активные магические способности\nВременный эффект\nТаргетное Заклинание\nНе чаще одного использования за сессию"},{"id":6,"name":"Криос","attributes":"Искусство + Атрибут Заявки + Защита + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Криос – искусство, которое позволяет замораживать объекты и управлять льдом.","type":1,"first_stage_name":"Закройте Окно","first_stage_description":"Охлаждает комнату, предмет или человека, редко причиняя реальный ущерб, но доставляя дискомфорт тем, кто чувствует перепад температуры. Количество успехов влияет на силу и длительность эффекта.","second_stage_name":"ХолодОк","second_stage_description":"Покрывает участок тела или какой-либо поверхности тонким слоем льда. Может обездвижить, но не нанести физический урон объекту заклинания, либо заставить застыть неживой объект. Число успехов определяет силу и длительность эффекта.","third_stage_name":"Доктор Фриз","third_stage_description":"Полностью замораживает объект колдовства, заставляя его потерять сознание и/или впасть в анабиоз. Практически ничто не может вывести из этого состояния подвергшегося колдовству, пока срок заклинания не истечет. Число успехов определяет длительность колдовства.","fourth_stage_name":"Последняя любовь Ковентины","fourth_stage_description":"Позволяет создать глыбу льда нужного заклинателю размера и обладающую определенными свойствами. Внутрь глыбы может быть помещен как какой-либо предмет, так и живое существо. При обработке льда с особыми свойствами, заклинатель может создать ледяной предмет с нужными характеристиками - к примеру, клинок, который будет прочным, как металл.","created_at":"2023-09-09T11:16:53.000000Z","updated_at":"2024-04-16T13:29:02.000000Z","deleted_at":null,"first_stage_condition":"Временный эффект\nИногда для успеха требуется \"перекинуть\" уровень локации.\nНе наносит урон","second_stage_condition":"Временный эффект\nНе наносит урон","third_stage_condition":"Таргетное заклинание\nВременный эффект\nНе наносит урона неживым объектам","fourth_stage_condition":"Таргетное заклинание\nВременный эффект\nНе наносит урон неживым объектам\nНе чаще одного использования за сессию"},{"id":41,"name":"Мать - Земля","attributes":"Искусство + Атрибут заявки + Защита + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Все мы вышли из Земли. И все мы в нее уйдем. По крайне мере так считаю многие древние народы и со старых времен они обращались к ней как заботливой Матери, надеясь на ее помощь и заступничество.","type":1,"first_stage_name":"Цветение Жизни","first_stage_description":"Заклинатель обращается к растениям и может расположить к себе любое из них, наполняя его жизненной силой. При успешном броске, заклинатель сможет вступить в лирический диалог с любым растением и/или получить от него посильную помощь.","second_stage_name":"Материнская любовь","second_stage_description":"Заклинатель покрывается земляной броней, которая может принимать магические и физические удары. Прочность брони, определяется успешностью броска. Заклинание можно использовать на другие цели. Броня не является помехой для движения объекта.","third_stage_name":"Заступничество","third_stage_description":"Заклинатель призывает магических элементалей Земли, которые могут выполнять защитные действия относительно колдующего. Но никогда не нападут. Успешность броска определяет количество и мощь элементалей. По истечении  времени они просто рассыплются на земляные комья.","fourth_stage_name":"Гнев Деметры","fourth_stage_description":"Заклинатель может раздвигать землю, устраивая землетрясение, создавая овраги и кратеры и менять окружающий ландшафт, начиная от создания оврагов, заканчивая локальными катаклизмами. Успешность броска влияет на мощь вызванных катаклизмов.","created_at":"2024-05-04T05:08:52.000000Z","updated_at":"2024-05-04T05:08:52.000000Z","deleted_at":null,"first_stage_condition":"Вы должны стоять на земле/камне.\nНеобходим телесный контакт.","second_stage_condition":"Можно использовать на несколько целей. \nНеобходим зрительный контакт, если вы создаете броню для других.\nВы должны стоять на земле/камне.","third_stage_condition":"Элементали только защищают.\nПризванные Элементали не способны к разговору и слаборазумны. Могут понять только очень короткие команды.\nВы должны стоять на земле/камне.","fourth_stage_condition":"Возможно использование не чаще одного раза за партию.\nНепредсказуемый результат.\nВы должны стоять на земле/камне."},{"id":7,"name":"Метаморфоза","attributes":"Искусство + Атрибут заявки + Телосложение + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Метаморфоза - это Искусство изменения формы живых существ. Благодаря этому колдовству заклинатель может легко стать тем, кем захочет, хотя бы на короткое время.","type":1,"first_stage_name":"Мантия Невидимка","first_stage_description":"Маскирует объект, делая его практически невозможным для обнаружения глазом. В отличие от Обмана или Фокусов, дает настоящую невидимость, но только зрительную - “невидимка” продолжает быть слышимым и осязаемым.","second_stage_name":"Трапеза с Алисой","second_stage_description":"Позволяет заклинателю изменить свой размер - стать либо крошечным, либо гигантским. Так же заклинатель может изменить размеры другого существа/объекта. Число успехов равно числу ходов, которое будет действовать заклинание, а также число тех, на кого может распространяться эффект.","third_stage_name":"Мейк-Ап","third_stage_description":"Даёт возможность изменить свой облик, повторив чужую внешность, либо превратиться в животное. Так же заклинатель может изменить и облик другого существа.  Можно применить только на одну цель.","fourth_stage_name":"Трудно быть Богом","fourth_stage_description":"Позволяет превратиться в мифическое существо со всеми его способностями и особенностями. Заклинатель может существовать и действовать в новой форме, но колдовать в такой форме гораздо сложнее. В зависимости от принятой формы, определяется группа атрибутов, на которые делается бросок с преимуществом.","created_at":"2023-09-09T11:24:14.000000Z","updated_at":"2025-10-27T04:32:17.000000Z","deleted_at":null,"first_stage_condition":"Временный эффект\nНевидимость распространяется на всех включая заклинателя и объекты заклинания ( если вы наложите заклинание на несколько целей, то друг друга вы так же не будете видеть)\nТолько на живые объекты\nС каждой дополнительной целью увеличивается сложность броска","second_stage_condition":"Временный Эффект\nТолько на живые объекты\nС каждой дополнительной целью увеличивается сложность броска","third_stage_condition":"Временный эффект\nТаргетное заклинание\nНеобходимо знать подробности повторяемой внешности\nНе дает бросков с преимуществом.\nТолько на живые объекты","fourth_stage_condition":"Временный эффект\nТаргетное заклинание\nРаботает только на заклинателя.\nНеобходимо знать подробности повторяемой внешности и имя\nНе дает броска с преимуществом\nНе чаще одного использования за сессию\nТолько на живые объекты"},{"id":8,"name":"Обман","attributes":"Искусство + Атрибут заявки + Обман + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Обман отвечает за искажение чужого восприятия и даёт возможность контролировать чужой разум. Обман требует прямого контакта - объект заклинания обязательно должен видеть или слышать колдующего. Обман работает только на одну цель.","type":1,"first_stage_name":"И снова Опиум","first_stage_description":"Позволяет исказить сенсорное восприятие объекта. Эффект работает только в режиме наложения: нельзя создать шум в тишине или заставить слепого видеть. Не наносит урона, но может заставить заклинаемого случайно причинить себе вред из-за нарушения восприятия мира. Также может быть использовано для отвода глаз от заклинателя, либо от какого бы то ни было объекта.","second_stage_name":"MIB","second_stage_description":"Заклинатель может стирать или похищать части воспоминаний и убеждений, или же производить точечное удаление воспоминаний. К примеру, он может уничтожить только воспоминание о том мгновении, когда объект колдовства врезался в него, следуя вниз по улице. Можно создать иллюзорное ложное воспоминание взамен стертого, либо оставить пустое пространство.","third_stage_name":"Клиническая Психотерапия","third_stage_description":"Даёт контроль над эмоциями жертвы. При наличии опоры на реальные чувства/воспоминания объекта, сложность колдовства снижается. Также, при помощи данного заклинания, можно вернуть/восстановить утраченные/померкшие воспоминания.","fourth_stage_name":"Манипулятивный Абьюз","fourth_stage_description":"При помощи этой магии, заклинатель может внести в характер объекта своего колдовства настолько большие изменения, что тот станет другой личностью. Также, при желании, колдующий может полностью подчинить объект своей воле. Заклинание может воздействовать только на одну цель.","created_at":"2023-09-09T11:29:16.000000Z","updated_at":"2025-10-27T04:33:53.000000Z","deleted_at":null,"first_stage_condition":"Таргетное заклинание\nВременный эффект\nЗрительный/телесный контакт/аудиальный контакт\nОбъект должен вас слышать\nЭффект наложения\nОбъект должен быть разумным","second_stage_condition":"Таргетное Заклинание\nЗрительный/телесный контакт\nОбъект должен вас слышать\nОбъект должен быть разумным","third_stage_condition":"Таргетное Заклинание\nЗрительный/телесный контакт\nОбъект должен вас слышать\nОбъект должен быть разумным","fourth_stage_condition":"Таргетное Заклинание\nЗрительный/телесный контакт\nОбъект должен вас слышать\nОбъект должен быть разумным\nВозможен непредсказуемый эффект\nНе чаще одного использования за сессию"},{"id":9,"name":"Пламя","attributes":"Искусство + Атрибут Заявки + Нападение + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Еще миллион лет назад смертные открыли для себя притягательность и красоту огня. Феи играли с его прекрасной мощью гораздо дольше. Они могут контролировать блуждающие огоньки и создавать слуг, состоящих из живого пламени.","type":1,"first_stage_name":"Горячо-Холодно","first_stage_description":"Заклятие поиска цели, указывающее место нахождения нужного предмета/места/существа. Блуждающий огонёк может принять либо форму шара, либо окружить свечением объект поиска, либо проявиться каким-либо ещё образом, обозначая направление или местоположение цели. Это пламя не имеет повышенной температуры и не способно согреть или нанести урон.","second_stage_name":"Кулак Прометея","second_stage_description":"Это колдовство позволяет полностью окружить определенный неодушевленный объект пламенем. Это пламя не будет наносить какого-либо урона ни заклинателю, ни данном объекту, но будет воздействовать на все остальное извне. Данное колдовство очень часто используется для того, чтобы зажигать оружие, которое после этого наносит противникам ужасные раны.","third_stage_name":"Молот Ведьм","third_stage_description":"Это колдовство позволяет окружить объект всепожирающим огнем, который быстро поглощает его. Огонь является обычным пламенем сразу же после своего появления, обжигая и сжигая объект воздействия данного колдовства так же, как если бы это было обычное пламя. Так же оно наносит урон заклинателю, если тот попытается прикоснуться к нему. .","fourth_stage_name":"Дитя Сопряжения","fourth_stage_description":"С помощью этого колдовства заклинатель может превратить что/кого угодно в живое пламя, сохранив при этом все присущие данному объекту качества и способности - кот останется котом, меч останется мечом, человек сможет двигаться и думать, и так далее.","created_at":"2023-09-09T11:32:56.000000Z","updated_at":"2025-10-27T04:34:40.000000Z","deleted_at":null,"first_stage_condition":"Не наносит урон\nВременный эффект\nМагическое пламя\nЗаклинатель должен точно знать, как выглядит и чем является искомый объект","second_stage_condition":"Временный эффект\nМагическое пламя\nРаботает только на неодушевленные объекты","third_stage_condition":"Таргетное заклинание\nВозможен непредсказуемы эффект","fourth_stage_condition":"Временный эффект\nМагическое пламя\nВозможен непредсказуемы эффект\nНе чаще одного использования за сессию"},{"id":10,"name":"Правление","attributes":"Искусство + Атрибут заявки + Манипулирование + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"В древние времена, Правители использовали Искусство Правления для того, чтобы регулярно навязывать свои благородные эдикты простолюдинам. Некоторые делают это и по сей день. Искусство Правления заставляет простолюдинов и аристократов, занимающих равное или более низкое положение, подчиняться приказам заклинателя.\nИскусство недоступно для изучения на старте игры. Только специалист в этом искусстве может поделится знаниями с другими.","type":1,"first_stage_name":"Огни Гондора","first_stage_description":"Заклинатель произносит воодушевляющую речь, убеждающую всех в зоне колдовства откликнуться на зов и прийти на помощь.","second_stage_name":"Путь Блиновской","second_stage_description":"Заклинатель вызывает восторг, священный трепет или любое другое нужное чувство у окружающих, и может выглядеть в чужих глаза словно бог. Цель/цели не могут не повиноваться приказу колдующего, но смутно ощущают неестественность желания подчиниться.","third_stage_name":"Смерть Медвежатника","third_stage_description":"Оберг не позволяет переступить порог или взять предмет, на который он наложен. Он может использоваться в качестве “волшебного замка”, пропуская только определенных людей/иных существ, и как защита от чужой магии. Сила Оберега зависит от числа успехов.","fourth_stage_name":"МФО","fourth_stage_description":"Действует как принудительная клятва, неисполнение которой карается проклятием, либо как запрет, не дающий заклинаемому совершить то или иное действие. Невыполнимые Клятвы или Запреты (например, Запрет дышать) сразу же спадают со своих целей. Сила Запрета, Клятвы или Проклятия зависит количества выброшенных успехов.","created_at":"2023-09-09T11:37:31.000000Z","updated_at":"2024-01-26T13:04:26.000000Z","deleted_at":null,"first_stage_condition":"Необходимо, чтобы объекты колдовства Вас слышали\nЦель не может причинить умышленного вреда себе или окружающим\nДействует только на разумных существ\nВременный эффект","second_stage_condition":"Необходимо, чтобы объекты колдовства Вас слышали\nЦель не может причинить умышленного вреда себе\nДействует только на разумных существ\nВременный эффект","third_stage_condition":"Оберег является Правилом.","fourth_stage_condition":"Не может заставить причинить умышленный вред себе\nДействует только на разумных существ\nЗрительный/Телесный контакт\nЯвляется правилом\nНе чаще одного использования за сессию"},{"id":11,"name":"Предсказания","attributes":"Искусство + Атрибут заявки + Проницательность + Право Рождение/Иной бонус + Сокровище/Снаряжение","description":"Позволяет пассивно взаимодействовать с Временем и Вероятностью. Искусство позволяет видеть прошлое, настоящее и вероятные итерации будущего.","type":1,"first_stage_name":"Взгляд Фиби","first_stage_description":"Позволяет заклинателю видеть прошлое объекта заклятия.","second_stage_name":"Глазок","second_stage_description":"Заклинатель может видеть и слышать через вещь, точное географическое местоположение, которой ему известно. При использовании  предварительно зачарованного предмета, необязательно знать его местоположение.","third_stage_name":"Осуждение Фортуны","third_stage_description":"Даёт заклинателю создать бафф или дебафф на определенный Атрибут на ближайший ход. Количество успехов определяет силу действия эффекта.","fourth_stage_name":"Слепая Пряха","fourth_stage_description":"Это колдовство позволяет определить и изменить судьбу объекта таким образом, чтобы нужная заклинателю вероятность развития событий в существовании объекта стала главенствующей. Механизм Слепой Пряхи даёт заклинателю силу определить судьбу объекта заклятия, после чего выбрать из предложенных наиболее комфортный ему вариант или предложить свой. В последнем случае результат может оказаться непредсказуемым.","created_at":"2023-09-09T11:48:59.000000Z","updated_at":"2024-01-26T13:05:00.000000Z","deleted_at":null,"first_stage_condition":"Таргетное заклинание\nРаботает только на неодушевленные предметы\nТелесный контакт","second_stage_condition":"Таргетное заклинание\nРаботает только на неодушевленные предметы\nВременный эффект\nЗнание точного внешнего вида объекта\nЗаклинатель видит лишь настоящее","third_stage_condition":"Таргетное заклинание\nРаботает только на \"Живые\" объекты\nЗрительный/телесный контакт\nВременный эффект\nНельзя использовать на себя","fourth_stage_condition":"Таргетное заклинание\nРаботает только на NPC\nРаботает только на \"Живые\" объекты\nЗрительный/телесный контакт\nВозможен непредсказуемый эффект\nНе чаще одного использования за сессию\n(Возможен мастерский произвол. Автор текста настоятельно рекомендует не применять это заклинание)"},{"id":12,"name":"Ремесло Историй","attributes":"Искусство + Атрибут заявки + Харизма + Право Рождение/Иной бонус + Сокровище","description":"Главной составляющей данного Искусства или тех Банков, которые применяются для него, всегда должна выступать некая форма повествования. Это повествование может преподноситься в любом виде, начиная поэзией и заканчивая песнями, но, в любом случае, его присутствие является обязательным.","type":1,"first_stage_name":"Бита Арлекино","first_stage_description":"Позволяет заклинателю определить настроение публики и настроить её на нужный лад. Идея или эмоция должна быть достаточно простой для того, чтобы это можно было выразить в одном или двух словах, и не может представлять собой приказ. Заклинатель также не может воздействовать на реакцию публики.","second_stage_name":"Премьера Аватара","second_stage_description":"Заклинатель притягивает к себе обрывки чужих мыслей и может создать на их основе ряд визуальных и звуковых иллюзий, которые будут иллюстрировать рассказываемую заклинателем историю. Иллюзии, созданные таким образом, не могут тактильно взаимодействовать ни с чем и причинять вред, не обладают разумом, но могут запутать, деморализовать или наоборот воодушевить тех, кто из видит.","third_stage_name":"Болтливый Патронус","third_stage_description":"Слова могут ранить и защитить. Заклинатель начинает рассказ, и в сочетании с темой истории он создает вокруг себя из слов и образов либо щит, либо оружие. Колдовство действует только пока рассказчик говорит, как только он замолкает или сильно сбивается - эффект пропадает. Щитом можно так же накрывать других персонажей/объекты..","fourth_stage_name":"Настоящий Мальчик","fourth_stage_description":"Колдующий начинает рассказывать историю, и в процессе рассказа появляется материальная иллюзия, способная стать полноценным живым существом и осознать себя. Некоторые утверждают, что именно так появился Пинокио.","created_at":"2023-09-09T11:55:42.000000Z","updated_at":"2023-09-11T11:19:45.000000Z","deleted_at":null,"first_stage_condition":"Объекты заклинания должны слышать Заклинателя\nРаботает только на разумных существ","second_stage_condition":"Не телесное\nОбъекты должны видеть/слышать Заклинателя\nРаботает только на разумных существ","third_stage_condition":"Обязателен лирический отыгрыш\nНевозможность совершить другое действие","fourth_stage_condition":"Возможен непредсказуемый результат\nНевозможность совершить другое действие\nНе чаще одного использования за сессию"},{"id":4,"name":"Рунология","attributes":"Искусство + Атрибут заявки + Интеллект +Право рождения/Иной бонус + Сокровище/Снаряжение","description":"Это магия давно забыта даже самыми древними существами на Материке. Возможно они лукавят, но у них определенно есть причины хранить в секрете даже память о силе способной влиять на реальность. Только специалист в этом искусстве может поделится знаниями с другими.","type":1,"first_stage_name":"Почти Белль","first_stage_description":"Данное заклинание позволяет прочесть любой текст, написанный на любом языке, и понять его содержание. Даже если написанное было защищено какой-либо магией или шифром.","second_stage_name":"Магический GPS","second_stage_description":"Этим заклинанием можно определить наличие наложенных чар на предмет/локацию/существо. При успешном броске можно определить не только наличие, но и цель, эффект или автора колдовства.","third_stage_name":"Синдром Отмены","third_stage_description":"Это заклинание позволяет аннулировать действие определенных рун или стереть их и вовсе.","fourth_stage_name":"Стрит-Арт","fourth_stage_description":"Колдовство, позволяющее нанести определенные руны с различными магическими эффектами. При нанесении руны с определенным значением на предмет, она может обрести определенное свойство.","created_at":"2023-09-09T10:58:49.000000Z","updated_at":"2024-01-26T13:15:27.000000Z","deleted_at":null,"first_stage_condition":"Если текст носит заклятие, то оно может подействовать на чтеца\nПеревод видит только заклинатель","second_stage_condition":"Работает только на определение и получение информации\nИнформацию получает только заклинатель","third_stage_condition":"В некоторых случаях невозможно отменить действие полностью и эффект будет временным\nЗаклинатель должен знать наверняка о наложенных рунах и их назначении","fourth_stage_condition":"Таргетное заклинание\nДля использования колдовства требуются особые магические расходники и особые знания ( книги или схемы).\nНе чаще одного раза за сессию\nВозможен непредсказуемый эффект"},{"id":39,"name":"Среда Настроений","attributes":"Искусство + Атрибут заявки + Проницательность + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Искусство построенное на эмоциях. Умение позволяющее лучше чувствовать и понимать мир вокруг себя, а порой и заставить мир испытать ваше эмоциональное состояние на себе.\nИскусство обязательно к отыгрышу \"банка\".","type":1,"first_stage_name":"Эмоциональный интеллект","first_stage_description":"Колдовство дает возможность настроиться на собеседника и при успехе считать наполняющие его эмоции. От доминирующих в данный момент, до самых потаенных. Считав объект, заклинатель может выбрать одну эмоцию из имеющихся и либо усилить, либо ослабить ее. Сила эффекта. определяет успешностью броска.","second_stage_name":"У страха глаза велики","second_stage_description":"Заклинатель присматривается к объекту колдовства и может отыскать его главную фобию. При успехе, заклинатель может усилить чувство страха и тревоги у объекта вводя его буквально в панический ужас.  Сила эффекта зависит от успешность броска.","third_stage_name":"Гневилион","third_stage_description":"Атакующая способность. Позволяет в ход подготовки вылить весь накопившийся гнев в следующий удар, который нанесете вы или ваша цель колдовства. Может быть использовано как \"бафф\". Удар нанесенный под эффектом Гневилиона полностью игнорирует материальную/физическую защиту цели.","fourth_stage_name":"Карнавал Эмоций.","fourth_stage_description":"В результате собственного эмоционального взрыва, заклинатель выпускает волну вокруг себя, которая охватывает окружающих и усиливает все эмоции, которые они испытывают в данный момент в десятки, а то и сотни раз. Подверженные этому эффекту, бросают абсолютно все свои дела полностью отдаваясь, свои чувствам. Результаты абсолютно не предсказуемы и могут иметь чудовищно разрушительные последствия. Дальность волны, сила усиления эмоций и длительность эффекта зависит от успешности броска.","created_at":"2024-05-04T04:18:57.000000Z","updated_at":"2024-05-04T04:18:57.000000Z","deleted_at":null,"first_stage_condition":"Заклинатель должен видеть объект.\nНе позволяет читать мысли.\nОбязателен отыгрыш банка.\nТаргетное Заклинание","second_stage_condition":"Зрительный контакт.\nТаргетное заклинание.\nОбязателен отыгрыш банка.","third_stage_condition":"Таргетное заклинание.\nЗаклинание подготовка.\nВы должны видеть цель, если это \"бафф\".\nЭффект накладывается на одушевленное существо, способное к атаке.\nОбязателен отыгрыш банка.","fourth_stage_condition":"Заклинание можно использовать не чаще одного раза за партию.\nВозможен непредсказуемый результат.\nЗаклинатель не выбирает конкретные цели воздействия.\nОбязателен отыгрыш банка.\n\nЗаклинателя просят сильно подумать о последствиях, перед использованием способности."},{"id":13,"name":"Странствия","attributes":"Искусство + Атрибут заявки + Внимание + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Искусство Странствий является Искусством умелого путешествия.","type":1,"first_stage_name":"120+","first_stage_description":"Это колдовство позволяет заклинателю или какому-либо другому существу двигаться невообразимо быстро в течение непродолжительного времени. Другие воспринимают объект воздействия магии, как расплывающееся в воздухе пятно.","second_stage_name":"Бегущий по Ветру","second_stage_description":"Это колдовство позволяет объекту своего воздействия летать. При прямом контакте, персонаж может распространить эффект на другой объект, при этом масса того, что он собирается поднять с собой в воздух не важна.","third_stage_name":"Дырокол","third_stage_description":"Даёт возможность заклинателю открыть портал в любое место, если он точно знает, где оно находится или как выглядит.","fourth_stage_name":"Прыг-Скок","fourth_stage_description":"С помощью этого искусства, персонаж может исчезать и появляться в любом месте, в которое он хочет попасть. Заклинатель должен знать, видеть (или прорицать) или хотя бы обладать чем-то, что связано с местом его назначения. Если заклинатель забывает об этом условии, то колдовство может подействовать непредсказуемо. Е Работает  только на заклинателя.","created_at":"2023-09-09T12:00:58.000000Z","updated_at":"2025-10-27T04:35:12.000000Z","deleted_at":null,"first_stage_condition":"Только на одушевленные объекты\nТелесный контакт\nВременный эффект\nС каждой дополнительной целью увеличивается сложность броска.","second_stage_condition":"Только на одушевленные объекты\nЗрительный/телесный контакт\nВременный эффект\nС каждой дополнительной целью увеличивается сложность броска.","third_stage_condition":"Точное представление места назначение в мельчайших подробностях.\nИногда результат может быть непредсказуемым","fourth_stage_condition":"Таргетное \nМожно использовать только на себя\nТочное представление места назначение в мельчайших последствиях.\nВозможен непредсказуемый эффект\nНе чаще одного использования за сессию"},{"id":45,"name":"Страсть Стали","attributes":"Искусство + Атрибут заявки + Нападение + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Долгие века, многие считали род Аверно самыми талантливыми мечниками, передающими свое ремесло от отца к сыну. Но чтобы быть лучшим воином, мало хорошо владеть оружием в мире колдовства.","type":1,"first_stage_name":"Наследие Эскалибура","first_stage_description":"Заклинатель настраивается на особенности предстоящей или текущей битвы и может перед боем или в процессе зачаровать свое оружие на устойчивость к определенной стихии. Длительность колдовства определяется успешностью броска. (Например: защититься от скованности движения рук с оружием в воде или бушующем ветре, дать ему устойчивость к огню и так далее)","second_stage_name":"Проклятие Пацифизма","second_stage_description":"Заклинатель видит слабину оружия оппонента и  может проклясть его оружие и все действия вашего противника будут совершаться с повышенной сложностью/помехой/и тем и другим в зависимости от успешности броска, лирической заявки и лирической составляющей.","third_stage_name":"Мечник Дикого Запада","third_stage_description":"Заклинатель зачаровывает клинок, становясь с ним одним целым, что значительно ускоряет его действия и движения, давая ему возможность совершить два действия в свой ход в боевой сцене. Длительность эффекта зависит от числа успехов.","fourth_stage_name":"Зов Аверно","fourth_stage_description":"Все услышавшие зов потомки рода Аверно приходят на помощь к заклинателю в призрачной форме и сражаются на его стороне. Не смотря на их призрачность, они наносят вполне ощутимый урон врагам. Успешность броска влияет на количество призраков, и длительность их присутствия в битве.","created_at":"2025-10-27T04:45:34.000000Z","updated_at":"2025-10-27T04:45:34.000000Z","deleted_at":null,"first_stage_condition":"Таргетное заклинание\nКолдовство работает только на неодушевленные предметы\nКолдовство работает только на оружие\nКолдовство имеет временный эффект\nКолдовство работает только на конкретно указанную стихию","second_stage_condition":"Таргетное заклинание\nКолдовство работает только на неодушевленные предметы\nКолдовство работает только на оружие\nКолдовство имеет временный эффект","third_stage_condition":"Таргетное заклинание\nКолдовство работает только на неодушевленные предметы\nКолдовство работает только на оружие\nКолдовство имеет временный эффект","fourth_stage_condition":"Требуется лирический отыгрыш\nКолдовство имеет временный эффект\nЗаклинатель не управляет действиями призраков при их появлении\nВозможен непредсказуемый эффект\nНе чаще одного использования за сессию"},{"id":14,"name":"Управление Небесами","attributes":"Искусство + Атрибут Заявки + Храбрость+ Право Рождения/Иной бонус + Сокровище/Снаряжение.","description":"Редко встречающееся искусство управления погодой, чаще всего известное только подводным и воздушным обитателям. Однако, срабатывает оно не всегда – есть такие места, которые защищены от воздействия этого волшебства – например подводные глубины. Вся магия этого искусства строится на сочетании стихии воздуха и воды.","type":1,"first_stage_name":"Пафос Морганы","first_stage_description":"Это колдовство позволяет управлять облаками и призвать туманы. В зависимости от желания персонажа и количества успехов, выброшенных игроком, заклинатель может вызвать и лёгкий туман, который можно будет разогнать, и непроглядное тёмное облако, не позволяющее разглядеть  ничего дальше расстояния вытянутой руки.","second_stage_name":"Танец с Бубном","second_stage_description":"Это колдовство позволяет призвать дождь. В зависимости от желания персонажа и количества успехов, выброшенных игроком, колдующий может вызвать как легкую морось, так и тропический ливень, смывающий всё на своём пути.","third_stage_name":"Месть Прелюбодея","third_stage_description":"Заклинатель может призывать гром и разряд молнии. В зависимости от пожелания колдующего и числа успехов, выброшенных игроком, заклинатель может призвать как просто оглушающий звуком и светом удар молнии, как и мощный электрический разряд, способный покалечить или убить","fourth_stage_name":"Тайник Дейви Джонса","fourth_stage_description":"Заклинатель может управлять ветром и вызывать штормы и бури на море. В зависимости от цели колдующего и числа успехов, выброшенных игроком, заклинатель может призвать как направленный лёгкий порыв ветра, так и вызвать бурю и шквальный ветер. Призываемые этим колдовством шторма настолько мощные, что могут выйти из под контроля создателя.","created_at":"2023-09-09T12:04:52.000000Z","updated_at":"2023-09-11T11:24:31.000000Z","deleted_at":null,"first_stage_condition":"Возможен непредсказуемый эффект","second_stage_condition":"Возможен непредсказуемый эффект\nТолько в открытом пространстве","third_stage_condition":"Возможен непредсказуемый эффект\nТолько в открытом пространстве","fourth_stage_condition":"Возможен непредсказуемы эффект\nДействует только в водной среде\nНе чаще одного использования за сессию"},{"id":15,"name":"Фокусы","attributes":"Искусство + Атрибут Заявки + Ловкость + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Искусство ловкости рук и иллюзий. Позволяет создавать материальные иллюзии и воздействовать на реальный мир, в отличие от Обмана.","type":1,"first_stage_name":"Акцио","first_stage_description":"Притягивание позволяет перемещать материальные вещи/существ с помощью телекинеза. С помощью этого колдовства они могут двигать, вращать, метать, поднимать и разбивать предметы, и чинить всевозможные препятствия.","second_stage_name":"Три карты Монте","second_stage_description":"Это колдовство создает дубликат предмета, которое колдующий может видеть или к которому может прикасаться. Копия обладает всеми особенностями данного объекта, которые можно увидеть и ощутить. Тем не менее, колдовство является только внешним, так как внутренние качества объекта с помощью этой магии не передаются. Работает только на неживые объекты.","third_stage_name":"Следи за Дамой","third_stage_description":"Заклинатель может мгновенно перемещать вещи из одного места в другое. Действует это колдовство только в том случае, если персонаж точно знает, где находится предмет, либо видел его в течение нескольких последних минут, либо смотрит непосредственно на предмет в момент колдовства.","fourth_stage_name":"Ширма","fourth_stage_description":"Это колдовство представляет собой высшую степень создания иллюзий. Если Три Карты Монте способно создавать только неподвижную копию, то Ширма создают полноценные Призрачные Тени. Призрачная Тень - это управляемая материальная субстанция, способная выйти из подчинения заклинателя и уйти жить самостоятельно","created_at":"2023-09-09T12:20:54.000000Z","updated_at":"2025-10-27T04:36:00.000000Z","deleted_at":null,"first_stage_condition":"Таргетное заклинание\nЗрительный контакт\nРаботает только на неодушевленные объекты.","second_stage_condition":"Зрительный/телесный контакт\nРаботает только на неживые объекты\nТаргетное заклинание\nИллюзии будут осязаемы, но не могут нанести урона, рассыпаясь при столкновении. Созданные иллюзорные предметы не двигаются, без участия внешней силы или другого колдовства.","third_stage_condition":"Обязательное точное знание местоположение предмета\nТолько на неодушевлённые объекты\nТаргетное колдовство","fourth_stage_condition":"Таргетное колдовство\nМожет быть только одна иллюзия за применение\nВозможен непредсказуемый эффект\nНе чаще одного использования за сессию"},{"id":16,"name":"Дискордия","attributes":"Искусство + Атрибут заявки + Нападение + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Дискордия – крайне редкое Искусство, запрещенное для изучения Университетом высоких Надежд, но по прежнему встречающееся.","type":2,"first_stage_name":"Дом Зеркал","first_stage_description":"Это колдовство позволяет заклинателю создать множество магических копий самого себя. В зависимости от успешности заклятия и желания колдуна, “клоны” могут быть как полностью идентичными оригиналу, так и быть его упрощенными и/или искаженными версиями: иметь искаженные пропорции, быть размытыми силуэтами, быть лишенными объема и т.д. Основная цель этого колдовства – отвелечение и создание путанницы, и при желании, чтобы сбить с толку нападающего, колдун может создать своеобразный парад кривых зеркал, в каждом из которых будет он. Клоны могут двигаться, шуметь, быть пугающими, но не могут оказывать физическое воздействие и причинять реальный вред.","second_stage_name":"Лунная Походка","second_stage_description":"Это колдовство наделяет удары колдующего исключительной точностью, происходящей из удивительной скорости и изящества его движений. Бой – это танец, колдун ловит его ритм, синхронизируется с противником, и начинает предугадывать его действия. \nЕсли игрок использует Походку в ходе боя, то ко всем атакующим броскам он получает дополнительные кубы. 2 успеха = 1 дополнительному кубу. \nДействует на протяжении одной боевой сцены. Заклинание может быть сбито любым дезориентирующим эффектом.","third_stage_name":"Непростительное Доминирование","third_stage_description":"Это колдовство способно усилить оружие (или даже голые руки). Зачарованное с помощью этой магии оружие начинает светиться красноватым светом и наносит удвоенный урон. Каждая успешная атака автоматически понижает уровень противника на 1, если не является для него смертельной.\nКоличество успехов определяет длительность эффекта. 3 Успеха = 1 сцена.","fourth_stage_name":"Друг Вокруг","fourth_stage_description":"При использовании этого боевого заклинания, каждый нанесенный урон оппоненту восстанавливает заклинателя. Если заклинатель цел, то от его атак могут восстанавливаться его товарищи. Лечение распределяется без возможности метаобсуждения на усмотрение заклинателя. Для успеха необходимо перекинуть уровень цели хотя бы на 1. Каждый доставленный урон умножается на 2 и превращается в доступное лечение. Действие совершается в один ход и не имеет отложенного эффекта.","created_at":"2023-09-09T12:36:34.000000Z","updated_at":"2023-09-11T11:41:59.000000Z","deleted_at":null,"first_stage_condition":"Не осязаемость\nВременный эффект","second_stage_condition":"Можно использовать на несколько существ\nРаботает только на одушевленных существ\nВременный Эффект","third_stage_condition":"Временный эффект","fourth_stage_condition":"Таргетное заклинание.\nВременный эффект\nТакая атака работает только по \"Живым\" объектам\nНе чаще одного использования за сессию"},{"id":17,"name":"Магия Крови","attributes":"Искусство + Атрибут заявки + Науки + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Многие считают это искусство безнадежно утраченным и теперь оно упоминается лишь в книгах, и то без каких-либо уточнений. Оно довольно часто построено на жертвах и зачастую имеет очень непредсказуемый эффект.","type":2,"first_stage_name":"Информационное Пиратство","first_stage_description":"Имея кровь объекта, заклинатель может узнать его точное местонахождение, внешний вид и текущее физическое состояние. Число успехов определяет точность полученной информации.","second_stage_name":"Проклятие Иссушения","second_stage_description":"Это колдовство позволяет заклинателю на расстоянии незаметно для объекта выкачивать из него кровь. Для этого необходим зрительный контакт и чтобы объект имел открытую рану на теле (размер ее не имеет значения). Заклинатель может забирать украденную кровь себе и сохранять ее или же нет. Это проклятие может быть использовано в бою и будет наносить летальный урон. Для успешного колдовства нужно перекинуть уровень цели хотя бы на 1.","third_stage_name":"Начало","third_stage_description":"Это колдовство позволяет с помощью крови объекта попасть в его мысли. Вы можете украсть секрет, навязать идею, вызвать желание. Объект никогда не чувствует вмешательства извне даже после того как колдовство закончится. За одно колдовство, можно сделать лишь одну вещь из вышеперечисленных. Формулировка должна быть максимально точной. Для успешного броска надо превысить уровень цели хотя бы на 1. Общее число успехов обозначает мощность заклинания.","fourth_stage_name":"Хочу Контента","fourth_stage_description":"Это высшая степень магии крови. Принеся в жертву жизнь, заклинатель может призвать в этот мир демона/бога и загадать одно желание. Число успехов олицетворяет мощь демона/бог и его ограничения в способностях. После выполнения желания демон/бог исчезнет. А может и нет…Заклинание всегда имеет непредсказуемый эффект в зависимости от количества успехов и лирической составляющей.","created_at":"2023-09-09T12:40:40.000000Z","updated_at":"2024-06-07T13:50:39.000000Z","deleted_at":null,"first_stage_condition":"Таргетное заклинание\nКровь объекта","second_stage_condition":"Зрительный контакт\nОткрытая рана объекта\nТаргетное колдовство\nТолько на \"живые\" объекты\nВременный эффект","third_stage_condition":"Таргетное колдовство\nЗнание имени объекта\nОбъект должен быть разумным","fourth_stage_condition":"Жертва\nЗнание имени Демона/Бога\nНепредсказуемое колдовство\nНе чаще одного использования за сессию\n(Возможен мастерский произвол. Автор текста настоятельно рекомендует не применять это заклинание)"},{"id":18,"name":"Наваждение","attributes":"Искусство + Атрибут заявки + Скрытность + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Наваждение – это искусство иллюзий, позволяющее управлять памятью при помощи силы Туманов.","type":2,"first_stage_name":"Синдром Самозванца","first_stage_description":"Колдовство даёт возможность принять заклинателю чужое обличье, либо замаскировать кого-то. При этом внешний вид колдующего или объекта не меняется - меняется то, как его воспринимают другие. Вместе с этим, Синдром Самозванца притупляет внимание, привлекаемое колдующим и, если тот вдруг пропадает, то его окружение не придаст этому значения, в своей голове найдя произошедшему рациональное объяснение.\nДля того, чтобы продлить действие Синдрома, колдуну нужно иметь доступ к реальному аналогу своей “личины”. Нельзя воссоздавать Синдром Самозванца по памяти или наложить человека/существа/предмета, которого сейчас не существует/никогда не существовало. Для обновления колдовства требуется живой контакт с объектом копирования. Число успехов обозначает длительность действия эффекта и его силу.","second_stage_name":"Газлайтинг","second_stage_description":"Проникновение в разум. Как и Синдром Самозванца на самом деле не изменяет внешний облик колдуна, так и эта способность не может украсть воспоминание. Газлайтинг позволяет увести фокус внимания объекта колдовства от события/явления, которое содержится в воспоминании: не стереть, но забыть, либо заставить считать информацию из воспоминания ложной, и никогда не происходившей. Также, как это колдовство заставляет “забыть” что-то, оно может заставить объект колдовства наоборот, акцентироваться на каком-то воспоминании и информации в нём. Это может на какое-то время полностью поменять мнение (не)человека по какому-то вопросу, т.к. он начнёт думать и рассуждать исходя из других предпосылок. \nТаким образом, достаточно сведущий в Наваждении колдун, может, на какое-то время, убедить объект своего колдовства практически в чём угодно. Для успешного колдовства необходимо перекинуть уровень цели. Общее число успехов обозначает длительность эффекта.","third_stage_name":"Защите Свидетелей","third_stage_description":"Если Синдром Самозванца позволяет замаскировать себя под другого и отвести взгляд от очевидных несоответствий в облике и поведении, то это колдовство позволяет сделать тоже самое с информационным следом колдуна. Использующий эту магию Заклинатель “отводит взгляд” от своей жизни. Он не заставляет себя исчезнуть, но о его существовании забывают, его лицо не замечают на фотографиях, при попытке прочесть письменные упоминания взгляд упорно не находит нужного имени и т.д. Попытки прочесть его ауру, указать к нему путь при помощи поисковых заклинаний, гадания и прочие сверхъестественные способы обнаружения также перестают работать либо частично, либо полностью. \nКак и в случае с Синдромом Самозванца, Защита Свидетелей может быть применена колдующим не только к самому себе, но и быть наложен на другое живое существо/объект.\nДалее, колдующий может “затемнить” информацию разово.\nЛибо совершить продолжительный ритуал и набрать определенное число успехов для того, чтобы продлить сокрытие на нужный себе срок.","fourth_stage_name":"Глубинные Воды","fourth_stage_description":"Если Газлайтинг, в сути своей, заставляет (не)человека самостоятельно, на основе собственного опыта поверить в ту или иную вещь, то это колдовство немного глобальнее. Колдующий не может предвидеть последствия Газлайтинга, но в случае с Глубинами Воли, он может получить именно ту реакцию, которая ему нужна. Объект заклятия полностью принимает “внушение”, сделанное колдуном: думает, говорит, эмоционально реагирует, чувствует и действует ровно так, как ему было велено. При этом, жертва принимает всё с ней происходящее за проявления собственной воли, агрессивно реагирует при попытках посторонних (не)людей ей помочь, защищает и оправдывает колдуна, наложившего на неё Глубины Воли. Когда действие заклинания проходит, жертва смутно помнит, что с ней происходило: время “безволия” вытесняется из её воспоминаний.\nКак и в случае с “Защитой Свидетелей”, заклятие можно наложить при помощи ритуала.","created_at":"2023-09-09T12:47:39.000000Z","updated_at":"2025-10-27T04:36:35.000000Z","deleted_at":null,"first_stage_condition":"Таргетное Заклинание\nТелесный контакт с объектом облика\nДействует только на живых\nВременный эффект.\nПри броске, заклинатель колдует на себе или объект, а не на оппонентов.","second_stage_condition":"Зрительный контакт\nОбъект должен слышать колдующего\nРаботает только на разумных существ\nТаргетное заклинание","third_stage_condition":"Зрительная/телесная связь с объектом\nТаргетное заклинание\nВременный эффект","fourth_stage_condition":"Зрительный контакт\nОбъект должен слышать колдующего\nВозможен непредсказуемый эффект\nДействует только на разумных существ\nНе чаще одного использования за сессию"},{"id":19,"name":"Некромантия","attributes":"Искусство + Атрибут заявки + Культура + Право Рождения/Иной бонус","description":"Это колдовство позволяет нарушить границу Жизни для получения информации, а иногда и для более материально помощи. Некромантия запрещена во всех Девяти королевствах согласно закону о Первого Королевства.","type":2,"first_stage_name":"Мертвый Взгляд","first_stage_description":"Это колдовство позволяет заклинателю связаться с мертвым существом и увидеть события, которые произошли при его жизни, его глазами. Дух не может отвечать на ваши вопросы, выдавать своей оценочное мнение  и ограничен в подаче информации для колдующего только картинкой происходящего от первого лица. При этом само желание мертвого не учитывается.  Для успеха надо перекинуть уровень покойного/локации/чар наложенных на него. Число успехов определяет количество видений.","second_stage_name":"Знания из-за границы","second_stage_description":"Вы можете связаться покойным и задать ему вопросы, на которые призванный дух будет обязан вам ответить честно вне зависимости от своего желания. Призванный дух может дать информацию лишь о том, что знал при жизни, включая свои теории и догадки. Для совершения колдовства требуется либо сам покойник, либо вещь, к которой он имел эмоциональную связь при жизни.","third_stage_name":"Кости Марионетки","third_stage_description":"Это темное колдовство дает возможность заклинателю оживить моторные функции любого мертвого существа. Одновременно можно поднять несколько мертвецов. Оживленные могут выполнить лишь одну несложную физическую задачу. Они лишены осознанного разума и являются лишь марионетками исполняющими волю колдуна. Они неспособны принимать решения и выполнять больше одной поставленной задачи. Во время колдовства вы можете дать только одну задачу, вне зависимости от числа поднятых “марионеток”. Для совершения колдовства, вам требуется иметь перед собой “тело” будущей “марионетки”.","fourth_stage_name":"Автономный Зомби","fourth_stage_description":"С помощью этой магии, колдун может воскресить любого умершего и дать ему свою волю или задание. При этом тело покойника примет здоровый вид его при жизни и может даже не догадываться о том, что является “зомби”. Колдун может дать возвращенному сложные социальные или боевые цели и задачи. За раз можно получить не больше одного “автономного зомби”.","created_at":"2023-09-09T13:34:50.000000Z","updated_at":"2023-09-11T12:04:36.000000Z","deleted_at":null,"first_stage_condition":"Объект заклятия должен быть мертв\nПлоть покойника или вещь с которой он имел эмоциональную связь\nТаргетное заклинание","second_stage_condition":"Объект заклятия должен быть мертв\nПлоть покойника или вещь с которой он имел эмоциональную связь\nТаргетное заклинание","third_stage_condition":"Объект должен быть мертв\nТело покойника","fourth_stage_condition":"Объект должен быть мертв\nТело покойника\nТаргетное заклинание\nНе чаще одного использования за сессию"},{"id":20,"name":"Презрение","attributes":"Искусство + атрибут Заявки + Храбрость + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"У аристократов есть Искусство Правление, которое помогает  править и насаждать правила. Презрение - это его противоположность, чье назначение эти правила нарушать, подрывать авторитеты и тому подобное.","type":2,"first_stage_name":"Насмешка","first_stage_description":"Данное колдовство не даёт объекту заклинания соблюдать местные социальные нормы. Число успехов определяет число ходов, в которые будет действовать заклинание. Позволяет защищаться от Правления.","second_stage_name":"Запах Свободы","second_stage_description":"Данное колдовство позволяет не повиноваться чужой власти и полностью игнорировать чужой авторитет, а также подталкивать к неповиновению других. Объекты воздействия заклинания становятся невосприимчивыми к любым формам команд и приказов. Может быть использован в качестве нейтрализации эффектов первых точек Правления и иной магии, направленной на подчинение и повиновение. Число успехов определяет число ходов, в которые будут действовать чары. Можно использовать на себя и окружение.","third_stage_name":"Болотная Память","third_stage_description":"Данное колдовство заставляет объект(ы) своего воздействия поднимать бунт и восстание против кого-либо/чего-либо, вызывая вспышку агрессивного анархического разгула в толпе. Поведение подвергшихся воздействию заклятия не контролируемо для колдующего. Нейтрализует собой первые точки Правления и другую магию, призывающую к повиновению. Число успехов определяет число подвергшихся магии людей.","fourth_stage_name":"Адвокат Дьявола","fourth_stage_description":"Колдующий может убедить кого угодно в чём угодно, и объект заклинания будет считать это истиной в последней инстанции. Благодаря этому эффекту, заклинатель может разрывать магические клятвы и договоры, как свои, так и чужие, в том числе снимать Гейсы - магические запреты, наложенные Правлением. Каждые 3 успеха = ослаблению клятвы/договора.","created_at":"2023-09-09T13:38:31.000000Z","updated_at":"2023-09-11T12:05:46.000000Z","deleted_at":null,"first_stage_condition":"Колдовство действует только на заклинателя.\nРаботает только на разумных существ","second_stage_condition":"Зрительный/телесный/аудио контакт с объектом колдовства\nРаботает только на разумных существ","third_stage_condition":"Зрительный/телесный/аудио контакт с объектом колдовства\nРаботает только на разумных существ\nНепредсказуемый результат\nВременный эффект\nНе чаще одного использования за сессию","fourth_stage_condition":"Зрительный/телесный/аудио контакт с объектом колдовства\nТаргетное заклинание\nРаботает только на разумных существ\nНе чаще одного использования за сессию"},{"id":21,"name":"Темное Ведовство","attributes":"Искусство + Атрибут заявки + Интеллект + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Это редкий вид магии встречающийся у редких ведьм. Даже те, кто владеют им не любят об этом распространяться. Но самое сложное в опасной и древней магии, что чтобы обучить кого-то этому искусству, недостаточно им просто обладать. Только специалист может поделиться тайнами темного колдовства.","type":2,"first_stage_name":"Темная Порча","first_stage_description":"Это искусство позволяет заклинателю навести сглаз на один объект. Сглаз всегда несет физический ущерб здоровью объекта колдовства. Это продолжительное колдовство с регулярным уроном, пока его не отменит заклинатель или кто-то, владеющий целебными чарами или артефактом. В противном случае Сглаз всегда рано или поздно заканчивается смертью. Число успехов сверх уровня объекта обозначает мощность заклинания.","second_stage_name":"Связь с миром","second_stage_description":"Эта часть ведовства позволяет заклинателю общаться с любыми живыми и мертвыми существами, независимо от их местонахождения и разницы в языках общения.  Объект может отказаться от диалога на свое усмотрение.","third_stage_name":"Темный лекарь","third_stage_description":"Тайные знания древней магии позволяют заклинателю излечить абсолютной любой из всех видов урона, а также снимать порчи, сглазы и некоторые другие магические эффекты наложенные на объект. Для этого колдовства всегда требуются магические расходники. Число успехов равно исцелению урона.  Во время исцеления заклинатель лишен возможности метаобщения.","fourth_stage_name":"Мир Теней","fourth_stage_description":"Позволяет заклинателю использовать тени, в качестве материальных помощников. Колдун может заставить тень живого существа выполнить любое физическое действие. Одновременно заклинатель может подчинить не больше одной тени. Число успехов определяет длительность заклинания и сложность задачи для Тени.","created_at":"2023-09-09T13:42:05.000000Z","updated_at":"2024-06-07T13:51:37.000000Z","deleted_at":null,"first_stage_condition":"Таргетное заклинание","second_stage_condition":"Для колдовства нужен либо прямой контакт с объектом, либо вещь имеющая эмоциональную связь с объектом.\nОбъект колдовства должен быть разумен\nТаргетное заклинание\nВременный эффект","third_stage_condition":"Телесный контакт\nМагические расходники\nТаргетное заклинание","fourth_stage_condition":"Таргетное заклинание\nДля колдовства нужно либо иметь зрительный контакт, либо вещь с которой объект имеет эмоциональную связь.\nВозможен непредсказуемый эффект\nНе чаще одного использования за сессию"},{"id":40,"name":"Чудеса Отражений","attributes":"Искусство + Атрибут заявки + Культура + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Давно забытое и по мнению многих утраченная Магия Зеркал","type":2,"first_stage_name":"Поиск Истины","first_stage_description":"Заклинатель может почувствовать, где находятся ближайшие окружающие его Зеркала в определенной локации. Так же он может войти в транс и посмотреть, что в данный момент отражает Зеркало, на которое он настроен. Кроме того, владеющий этим Искусством имеет особую связь с зеркалами, и может определить магические свойства Зеркала. Дальность радиуса поиска Зеркал а так же длительность просмотра и успешность определения магических свойств, зависит от успешности броска. Заклинателя в этот момент не могут увидеть.","second_stage_name":"Свет мой Зеркальце","second_stage_description":"Колдовство помогает узнать, многие чужие секреты. Заклинатель обращается к отражениям внутри любого Зеркала. Если они являются, то могут рассказать Заклинателю свидетелями чего они сталив рамках лирического диалога. Успешность броска определяет длительность нахождения отражения у поверхности.","third_stage_name":"Пути Семирамиды","third_stage_description":"Заклинание позволяет использовать Зеркала обычные или зачарованные, в качестве дверей для перемещения. Заклинатель может зайти в одно зеркало и выйти из другого.  Число успехов отражает стабильность прохода и возможность провести с собой кого то еще.","fourth_stage_name":"И свитер такой же синий.","fourth_stage_description":"Самые темный глубины Зеркал отражений могут призвать не просто призрачный осколок, а полноценное Отражение из Сияющего Пространства. Он может использовать его как советника или же выпустить его на волю, дав какую то цель. Допельгангер будет действовать на свое усмотрение, пока не выполнит Поставленную задачу. Что произойдет после выполнения цели неизвестно.","created_at":"2024-05-04T04:49:21.000000Z","updated_at":"2024-05-04T04:52:02.000000Z","deleted_at":null,"first_stage_condition":"Для определения магических свойств Зеркала нужен Телесный Контакт.\nЕсли заклинатель хочет посмотреть через зеркало, находясь в Сияющем Пространстве, то местонахождение Зеркала не имеет значение.\nВо время транса заклинатель не может совершать других действий.","second_stage_condition":"Для колдовства необходимо иметь Зеркало.\nЗаклинатель должен знать чье отражение он призывает ( либо может предоставить это на милость Фортуны)\nОтражение может поведать лишь о том, что оно видело через Зеркало, которое послужило объектом колдовства.\nОтражения не обязательно говорят правду.\nТелесный контакт с зеркалом.","third_stage_condition":"Для колдовства необходимо два Зеркала.\nЗаклинатель должен знать, где находится каждое зеркало и что оно отражает.\nНе позволяет проникнуть в Сияющее Пространство.","fourth_stage_condition":"Не чаще одного раза за партию ( а лучше вообще не надо).\nДопельгангер может извратить вашу цель в своей голове и выполнить ее не так, как вы планировали ( ну правда не надо).\nИмеет непредсказуемые последствия ( Я серьезно. Это хреновая идея).\nНеобходимо иметь зеркало, в котором хотя бы раз отражался тот, чьего Допельгангера вы хотите призвать. ( ну раз уж вы решили...)"}],"faerie":[{"id":22,"name":"Афродезия","attributes":"Искусство + Королевство + Манипулирование + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Афродезия - это искусство соблазнения и манипуляции чужими чувствами, позволяя навязать объекту практически любые нужные вам цели.","type":3,"first_stage_name":"Любовь с первого Взгляда","first_stage_description":"Объект заклятия ощущает безоговорочную симпатию к заклинателю, даже если он до этого никогда не видел или не обращал на него внимания","second_stage_name":"Книга Души","second_stage_description":"Позволяет проникнуть в чувства объекта и узнать, что/кого он вожделеет. Успешность броска влияет на количество и качество полученной информации.","third_stage_name":"Маниакальная Фаза","third_stage_description":"Вызывает безумную кратковременную одержимость кем-либо/чем-либо. Жертва, подвергшаяся заклятию, настолько нуждается в каком-либо объекте, что готова пойти на что угодно (кроме нанесения себе непосредственного урона) ради его получения. В том числе - принести в жертву/уничтожить объект желания ради удовлетворения жажды. Каждые 2 или 3 успеха = 1 сцена действия эффекта.","fourth_stage_name":"Стокгольмский Синдром","fourth_stage_description":"Вызывает глубокую иррациональную привязанность и фанатичную одержимость выбранным заклинателем существом/объектом/местом/явлением. Побуждает объект заклятия делать всё ради получения предмета своей мании. Эффект полностью осмысленный и не проходит в течение ближайшего времени, только если заклинатель не снимет с жертвы заклятие сам (что может не получиться). Наложивший заклятье не может контролировать находящуюся в состоянии мании жертву. Для успешности броска достаточно одного успеха сверх уровня объекта.","created_at":"2023-10-05T09:56:45.000000Z","updated_at":"2025-10-27T04:38:24.000000Z","deleted_at":null,"first_stage_condition":"Таргетное заклинание\nОбязателен зрительный/телесный/аудио контакт с целью\nЦель должна быть разумной\nПосле спадания чар существо понимает, что его околдовали.\nВременный эффект","second_stage_condition":"Таргетное заклинание\nЗрительный/телесный\nТолько на разумных существ","third_stage_condition":"Таргетное заклинание\nЗрительный/телесный/аудио контакт\nТолько на разумных существ\nПосле спадания чар существо понимает, что его околдовали\nВременный Эффект\nНе работает на другие чувства осязания, кроме разума","fourth_stage_condition":"Таргетное заклинание\nЗрительный/телесный/аудио контакт\nТолько на разумных существ\nВозможен непредсказуемый эффект\nНе чаще одного использования за сессию."},{"id":35,"name":"Дискордия","attributes":"Искусство + Королевство + Нападение + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Дискордия – крайне редкое Искусство, но по прежнему встречающееся. Недоступно со старта.","type":3,"first_stage_name":"Дом Зеркал","first_stage_description":"Это колдовство позволяет заклинателю создать множество магических копий самого себя. В зависимости от успешности заклятия и желания колдуна, “клоны” могут быть как полностью идентичными оригиналу, так и быть его упрощенными и/или искаженными версиями: иметь искаженные пропорции, быть размытыми силуэтами, быть лишенными объема и т.д. Основная цель этого колдовства – отвлечение и создание путаницы, и при желании, чтобы сбить с толку нападающего, колдун может создать своеобразный парад кривых зеркал, в каждом из которых будет он. Клоны могут двигаться, шуметь, быть пугающими, но не могут оказывать физическое воздействие и причинять реальный вред.","second_stage_name":"Лунная Походка","second_stage_description":"Это колдовство наделяет удары колдующего исключительной точностью, происходящей из удивительной скорости и изящества его движений. Бой – это танец, колдун ловит его ритм, синхронизируется с противником, и начинает предугадывать его действия.\nЕсли игрок использует Походку в ходе боя, то ко всем атакующим броскам он получает дополнительные кубы. 2 успеха = 1 дополнительному кубу.\nДействует на протяжении одной боевой сцены. Заклинание может быть сбито любым дезориентирующим эффектом.","third_stage_name":"Непростительное Доминирование","third_stage_description":"Это колдовство способно усилить оружие (или даже голые руки). Зачарованное с помощью этой магии оружие начинает светиться красноватым светом и наносит удвоенный урон. Каждая успешная атака автоматически понижает уровень противника на 1, если не является для него смертельной.\nКоличество успехов определяет длительность эффекта. 3 Успеха = 1 сцена.","fourth_stage_name":"Друг Вокруг","fourth_stage_description":"При использовании этого боевого заклинания, каждый нанесенный урон оппоненту восстанавливает заклинателя. Если заклинатель цел, то от его атак могут восстанавливаться его товарищи. Лечение распределяется без возможности метаобсуждения на усмотрение заклинателя. Для успеха необходимо перекинуть уровень цели хотя бы на 1. Каждый доставленный урон умножается на 2 и превращается в доступное лечение. Действие совершается в один ход и не имеет отложенного эффекта.","created_at":"2023-10-05T10:40:28.000000Z","updated_at":"2023-10-05T11:07:29.000000Z","deleted_at":null,"first_stage_condition":"Не осязаемость\nВременный эффект","second_stage_condition":"Можно использовать на несколько существ\nРаботает только на одушевленных существ\nВременный Эффект","third_stage_condition":"Временный эффект","fourth_stage_condition":"Таргетное заклинание.\nВременный эффект\nТакая атака работает только по \"Живым\" объектам\nНе чаще одного использования за сессию"},{"id":23,"name":"Изначальность","attributes":"Искусство + Королевство + Науки+ Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Искусство взаимодействия с силами природы, общая элементальная магия.","type":3,"first_stage_name":"Посол Мира","first_stage_description":"Это колдовство позволяет говорить с чем угодно, даже с существами, которые изначально неспособны говорить или понимать человеческую речь. Число успехов определяет число задаваемых вопросов и полноту ответов, в зависимости от уровня существа/предмета/локации. 1/2/3 успеха = 1 ответу","second_stage_name":"Мать Тереза (была той еще сукой)","second_stage_description":"Имеет два варианта использования: \n1) Жизненная сторона: Наполняет цель/цели энергией жизни и позволяет исцелить любую рану. Число успехов определяет успешность исцеления. В случае лишних успехов, заклинатель, может забрать остаток лечения себе, но не может передать его кому-то другому, если такой заявки не было изначально. Если заклинатель хочет исцелить больше одной цели, то лечение он распределяет по своему усмотрению. Лечение идет по цене 1 Успех = 1 Тупой Урон.\n2) Сучья сторона: обращает энергию жизни в оружие против существ, в которых нет жизни. Число успехов влияет на успешность нанесения урона и количество этого урона.","third_stage_name":"Шаман-Кинг","third_stage_description":"Заклинатель, использующий это колдовство, может использовать один из следующих природных элементов: огонь, воду, землю, воздух. Число успехов влияет на мощность эффекта используемой стихии и его длительность. Иногда может выйти из под контроля заклинателя.","fourth_stage_name":"Неведомая Хтонь","fourth_stage_description":"Это колдовство позволяет заклинателю или объекту заклинания принять любой Облик. При этом объект заклятия получает броски с помехой и преимуществом на определенные группы атрибутов, в зависимости от особенностей нового Облика. Если колдующий принимает Облик мифического зверя, то не получает его магические способности. Число успехов определяет число ходов, на протяжении которых заклинатель использует Облик: 2 успех = 1 сцена при использовании обычного существа. 3 успеха =1 сцене при использовании Мифического существа. Для совершения колдовства необходимо лишь знать, как выглядит объект превращения.","created_at":"2023-10-05T10:02:20.000000Z","updated_at":"2025-10-27T04:39:23.000000Z","deleted_at":null,"first_stage_condition":"Магия действует только на живых существ и то, что подходит под понятие живого внутри мира ( деревья, растения, камни и т.п.) и может иметь хотя бы самый простой разум\nТаргетное заклинание\nВременный эффект","second_stage_condition":"Жизненная сторона действует только на живых существ и то, что подходит под понятие живого внутри мира ( деревья, растения)\nНе снимает проклятия\nНе разрушает магические контракты\nНе работает с материей времени\nНе лечит магические болезни и их эффекты/симптомы\nВ приоритете всегда лечатся Увечья по цене 3 успеха = 1 Увечье.\nСучья сторона: действует только на тех существ, которые определяются как нежить.\n(так же может действовать на некоторых порождений Холодного Простора, но это индивидуально)","third_stage_condition":"Заклинатель не может создать природный элемент этим искусством\nНе может увеличить количество воды или земли\nНе работает на магически измененные элементы\nТребует поддержания колдовства.( Во время его совершения, игрок не может совершать других действий, кроме разговорных)","fourth_stage_condition":"Не дает возможности принимать облик существ инородной магической природы\nДает возможность принять облик существ относящихся к виду \"Живых\" внутри мира\nНе передает активные магические способности\nВременный эффект\nТаргетное Заклинание\nНе чаще одного использования за сессию"},{"id":37,"name":"Именование","attributes":"Искусство + Королевство + Интеллект + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Крайне редкое и сложное в освоении Искусство, носители которого с осторожностью передают свои знания о нём. Именование позволяет обращаться к Истинным Именам существ и вещей, что в определенной мере даёт подменышу власть над тканью реальности. Не доступно на старте. Обучить ему может, лишь специалист в этом искусстве.","type":3,"first_stage_name":"Почти Белль","first_stage_description":"Данное заклинание позволяет прочесть любой текст, написанный на любом языке, и понять его содержание. Даже если написанное было защищено какой-либо магией или шифром.","second_stage_name":"404 Error","second_stage_description":"Этим заклинанием можно определить наличие наложенных чар на предмет/локацию/существо. При успешном броске можно определить не только наличие, но и цель, эффект или автора колдовства. Количество успехов определяет подробность полученной информации. При определенном количестве успехов, позволяет нивелировать эффект начертанных символов.","third_stage_name":"Маска, я тебя знаю!","third_stage_description":"Использование этого колдовства позволяет заклинателю определить Истинное имя своей цели. Каждое живое существо или предмет обладает Истинным Именем, и его знание даёт подменышу определённую власть над объектом заклинания.","fourth_stage_name":"Джей Кей Роулинг","fourth_stage_description":"Использование данного колдовства позволяет изменить Истинное Имя объекта заклятия при условии, что колдующему известно изначальное Истинное Имя. Это даёт возможность изменить существо или предмет на фундаментальном уровне.","created_at":"2023-10-05T10:54:42.000000Z","updated_at":"2023-10-05T11:08:40.000000Z","deleted_at":null,"first_stage_condition":"Если текст носит заклятие, то оно может подействовать на чтеца\nПеревод видит только заклинатель","second_stage_condition":"Только одна попытка заклинания ( перебросы не идут в расчёт попыток)","third_stage_condition":"Таргетное заклинание","fourth_stage_condition":"Таргетное заклинание\nИспользование 1 раз за сессию."},{"id":38,"name":"Инфузия","attributes":"Искусство + Королевство + Навыки + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Искусство созидания и изменения химерического мира вокруг.","type":3,"first_stage_name":"Взгляд Истины","first_stage_description":"Заклинатель может узнать особые навыки и способности артефакта/материала/химеры. Число успехов обозначает количество полученной информации.","second_stage_name":"Быстрее, выше, сильнее!","second_stage_description":"Это колдовство позволяет \"закалить\"(изменить) уже существующую случайную химеру/артефакт/материал. Химера, к которой было успешно применено данное колдовство, может быть обработана, либо выкована, как если бы была придуманной.","third_stage_name":"Самоделкин","third_stage_description":"Создание магических артефактов с нуля. Функциональность и внешний вид зависят от доступных ресурсов, назначения и общего уровня мастерства.\nКаждые 4 успеха дают артефакту 1 точку. Каждая точка сверху второй дает один случайный эффект на усмотрения мастера с учетом пожелания заклинателя.","fourth_stage_name":"It\u0027s alive! Aliiiiiiiiiiiive!!!","fourth_stage_description":"На высоких уровнях это Искусство становится изменением и созиданием химер в полном смысле этого слова.","created_at":"2023-10-05T11:03:18.000000Z","updated_at":"2025-10-27T04:37:27.000000Z","deleted_at":null,"first_stage_condition":"Информацию получает только заклинатель\nТелесный контакт\nТаргетное заклинание","second_stage_condition":"Таргетное заклинание\nТелесный контакт\nВозможен непредсказуемый эффект\nТребует расходных материалов\nНельзя менять материальное в химерическое и обратно.\nНе дает создание еды.","third_stage_condition":"Таргетное заклинание\nДля акта создания нужны расходные магические материалы и специальные инструменты для подобного действия.\nТелесный контакт\nВозможен непредсказуемый эффект\nНе чаще одного использования за сессию","fourth_stage_condition":"Требует расходных материалов\nТребует созидательных артефактов\n1 раз за сессию\nФизический контакт\nВозможен непредсказуемый эффект"},{"id":24,"name":"Криос","attributes":"Искусство + Королевство+ Защита + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Охлаждает комнату, предмет или человека, редко причиняя реальный ущерб, но доставляя дискомфорт тем, кто чувствует перепад температуры. Количество успехов влияет на силу и длительность эффекта.","type":3,"first_stage_name":"Закройте Окно","first_stage_description":"Охлаждает комнату, предмет или человека, редко причиняя реальный ущерб, но доставляя дискомфорт тем, кто чувствует перепад температуры. Количество успехов влияет на силу и длительность эффекта.","second_stage_name":"ХолодОк","second_stage_description":"Покрывает участок тела или какой-либо поверхности тонким слоем льда. Может обездвижить, но не нанести физический урон объекту заклинания, либо заставить застыть неживой объект. Число успехов определяет силу и длительность эффекта.","third_stage_name":"Доктор Фриз","third_stage_description":"Полностью замораживает объект колдовства, заставляя его потерять сознание и/или впасть в анабиоз. Практически ничто не может вывести из этого состояния подвергшегося колдовству, пока срок заклинания не истечет. Число успехов определяет длительность колдовства.","fourth_stage_name":"Последняя любовь Ковентины","fourth_stage_description":"Позволяет создать глыбу льда нужного заклинателю размера и обладающую определенными свойствами. Внутрь глыбы может быть помещен как какой-либо предмет, так и живое существо. При обработке льда с особыми свойствами, заклинатель может создать ледяной предмет с нужными характеристиками - к примеру, клинок, который будет прочным, как металл.","created_at":"2023-10-05T10:04:13.000000Z","updated_at":"2024-04-16T13:29:28.000000Z","deleted_at":null,"first_stage_condition":"Временный эффект\nИногда для успеха требуется \"перекинуть\" уровень локации.\nНе наносит урон","second_stage_condition":"Временный эффект\nНе наносит урон","third_stage_condition":"Таргетное заклинание\nВременный эффект\nНе наносит урона неживым объектам","fourth_stage_condition":"Таргетное заклинание\nВременный эффект\nНе наносит урон неживым объектам\nНе чаще одного использования за сессию"},{"id":42,"name":"Мать - Земля","attributes":"Искусство + Королевство + Защита + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Все мы вышли из Земли. И все мы в нее уйдем. По крайне мере так считаю многие древние народы и со старых времен они обращались к ней как заботливой Матери, надеясь на ее помощь и заступничество.","type":3,"first_stage_name":"Цветение Жизни","first_stage_description":"Заклинатель обращается к растениям и может расположить к себе любое из них, наполняя его жизненной силой. При успешном броске, заклинатель сможет вступить в лирический диалог с любым растением и/или получить от него посильную помощь.","second_stage_name":"Материнская любовь","second_stage_description":"Заклинатель покрывается земляной броней, которая может принимать магические и физические удары. Прочность брони, определяется успешностью броска. Заклинание можно использовать на другие цели. Броня не является помехой для движения объекта.","third_stage_name":"Заступничество","third_stage_description":"Заклинатель призывает магических элементалей Земли, которые могут выполнять защитные действия относительно колдующего. Но никогда не нападут. Успешность броска определяет количество и мощь элементалей. По истечении времени они просто рассыплются на земляные комья.","fourth_stage_name":"Гнев Деметры","fourth_stage_description":"Заклинатель может раздвигать землю, устраивая землетрясение, создавая овраги и кратеры и менять окружающий ландшафт, начиная от создания оврагов, заканчивая локальными катаклизмами. Успешность броска влияет на мощь вызванных катаклизмов.","created_at":"2024-05-04T05:11:11.000000Z","updated_at":"2024-05-04T05:11:11.000000Z","deleted_at":null,"first_stage_condition":"Вы должны стоять на земле/камне.\nНеобходим телесный контакт.","second_stage_condition":"Можно использовать на несколько целей.\nНеобходим зрительный контакт, если вы создаете броню для других.\nВы должны стоять на земле/камне.","third_stage_condition":"Элементали только защищают.\nПризванные Элементали не способны к разговору и слаборазумны. Могут понять только очень короткие команды.\nВы должны стоять на земле/камне.","fourth_stage_condition":"Возможно использование не чаще одного раза за партию.\nНепредсказуемый результат.\nВы должны стоять на земле/камне."},{"id":25,"name":"Метаморфоза","attributes":"Искусство + Королевство+ Телосложение+ Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Метаморфоза - это Искусство изменения формы живых существ. Благодаря этому колдовству заклинатель может легко стать тем, кем захочет, хотя бы на короткое время.","type":3,"first_stage_name":"Мантия Невидимка","first_stage_description":"Маскирует объект, делая его практически невозможным для обнаружения глазом. В отличие от Обмана или Фокусов, дает настоящую невидимость, но только зрительную - “невидимка” продолжает быть слышимым и осязаемым. Число успехов равно числу ходов, которое будет действовать заклинание, а также число тех, на кого может распространяться эффект. 2 успеха = 1 сцена невидимости. При колдовстве на несколько целей повышается сложность броска.","second_stage_name":"Трапеза с Алисой","second_stage_description":"Позволяет заклинателю изменить свой размер - стать либо крошечным, либо гигантским. Так же заклинатель может изменить размеры другого существа/объекта. Число успехов равно числу ходов, которое будет действовать заклинание, а также число тех, на кого может распространяться эффект. 2 успеха = 1 сцена действия. При колдовстве на несколько целей повышается сложность колдовства.","third_stage_name":"Мейк-Ап","third_stage_description":"Даёт возможность изменить свой облик, повторив чужую внешность, либо превратиться в животное. Так же заклинатель может изменить и облик другого существа. Число успехов определяет число ходов, в которые будет действовать заклинание. 2 успеха = 1 сцене. При превращении в животное, число успехов добавляется к броску по 2 атрибутам (2 к 1), которые являются профильными для существа. К примеру, превратившись в небольшое животное или птицу, заклинатель прибавляет успехи броска на метаморфозу к Ловкости, Скрытности; при превращении в крупного зверя - к Телосложению, Нападению и так далее. Можно применить только на одну цель.","fourth_stage_name":"Трудно быть Богом","fourth_stage_description":"Позволяет превратиться в мифическое существо со всеми его способностями и особенностями. Заклинатель может существовать и действовать в новой форме, но сложность магических бросок возрастает до 8. В зависимости от принятой формы, определяется группа атрибутов, на которые делается бросок с преимуществом.","created_at":"2023-10-05T10:06:55.000000Z","updated_at":"2025-10-27T04:40:34.000000Z","deleted_at":null,"first_stage_condition":"Временный эффект\nНевидимость распространяется на всех включая заклинателя и объекты заклинания ( если вы наложите заклинание на несколько целей, то друг друга вы так же не будете видеть)\nТолько на живые объекты\nС каждой дополнительной целью увеличивается сложность броска.","second_stage_condition":"Временный Эффект\nТолько на живые объекты\nС каждой дополнительной целью увеличивается сложность броска.","third_stage_condition":"Временный эффект\nТаргетное заклинание\nНеобходимо знать подробности повторяемой внешности\nНе дает бросков с преимуществом.\nТолько на живые объекты","fourth_stage_condition":"Временный эффект\nТаргетное заклинание\nНеобходимо знать подробности повторяемой внешности и имя\nНе дает броска с преимуществом\nНе чаще одного использования за сессию\nТолько на живые объекты\nРаботает только на заклинателя."},{"id":36,"name":"Наваждение","attributes":"Искусство + Королевство + Скрытность + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Наваждение – это искусство иллюзий, позволяющее управлять памятью при помощи силы Туманов. Не доступно со старта.","type":3,"first_stage_name":"Синдром Самозванца","first_stage_description":"Колдовство даёт возможность принять заклинателю чужое обличье, либо замаскировать кого-то. При этом внешний вид колдующего или объекта не меняется - меняется то, как его воспринимают другие. Вместе с этим, Синдром Самозванца притупляет внимание, привлекаемое колдующим и, если тот вдруг пропадает, то его окружение не придаст этому значения, в своей голове найдя произошедшему рациональное объяснение.\nДля того, чтобы продлить действие Синдрома, колдуну нужно иметь доступ к реальному аналогу своей “личины”. Нельзя воссоздавать Синдром Самозванца по памяти или наложить человека/существа/предмета, которого сейчас не существует/никогда не существовало. Для обновления колдовства требуется живой контакт с объектом копирования. Число успехов обозначает длительность действия эффекта и его силу.","second_stage_name":"Газлайтинг","second_stage_description":"Проникновение в разум. Как и Синдром Самозванца на самом деле не изменяет внешний облик колдуна, так и эта способность не может украсть воспоминание. Газлайтинг позволяет увести фокус внимания объекта колдовства от события/явления, которое содержится в воспоминании: не стереть, но забыть, либо заставить считать информацию из воспоминания ложной, и никогда не происходившей. Также, как это колдовство заставляет “забыть” что-то, оно может заставить объект колдовства наоборот, акцентироваться на каком-то воспоминании и информации в нём. Это может на какое-то время полностью поменять мнение (не)человека по какому-то вопросу, т.к. он начнёт думать и рассуждать исходя из других предпосылок.\nТаким образом, достаточно сведущий в Наваждении колдун, может, на какое-то время, убедить объект своего колдовства практически в чём угодно. Для успешного колдовства необходимо перекинуть уровень цели. Общее число успехов обозначает длительность эффекта.","third_stage_name":"Защита Свидетелей","third_stage_description":"Если Синдром Самозванца позволяет замаскировать себя под другого и отвести взгляд от очевидных несоответствий в облике и поведении, то это колдовство позволяет сделать тоже самое с информационным следом колдуна. Использующий эту магию Заклинатель “отводит взгляд” от своей жизни. Он не заставляет себя исчезнуть, но о его существовании забывают, его лицо не замечают на фотографиях, при попытке прочесть письменные упоминания взгляд упорно не находит нужного имени и т.д. Попытки прочесть его ауру, указать к нему путь при помощи поисковых заклинаний, гадания и прочие сверхъестественные способы обнаружения также перестают работать либо частично, либо полностью.\nКак и в случае с Синдромом Самозванца, Защита Свидетелей может быть применена колдующим не только к самому себе, но и быть наложен на другое живое существо/объект.\nДалее, колдующий может “затемнить” информацию разово.\nЛибо совершить продолжительный ритуал и набрать определенное число успехов для того, чтобы продлить сокрытие на нужный себе срок.","fourth_stage_name":"Глубинные Воды","fourth_stage_description":"Если Газлайтинг, в сути своей, заставляет (не)человека самостоятельно, на основе собственного опыта поверить в ту или иную вещь, то это колдовство немного глобальнее. Колдующий не может предвидеть последствия Газлайтинга, но в случае с Глубинами Воли, он может получить именно ту реакцию, которая ему нужна. Объект заклятия полностью принимает “внушение”, сделанное колдуном: думает, говорит, эмоционально реагирует, чувствует и действует ровно так, как ему было велено. При этом, жертва принимает всё с ней происходящее за проявления собственной воли, агрессивно реагирует при попытках посторонних (не)людей ей помочь, защищает и оправдывает колдуна, наложившего на неё Глубины Воли. Когда действие заклинания проходит, жертва смутно помнит, что с ней происходило: время “безволия” вытесняется из её воспоминаний.\nКак и в случае с “Защитой Свидетелей”, заклятие можно наложить при помощи ритуала.","created_at":"2023-10-05T10:43:17.000000Z","updated_at":"2025-10-27T04:43:26.000000Z","deleted_at":null,"first_stage_condition":"Таргетное Заклинание\nТелесный контакт с объектом облика\nДействует только на живых\nВременный эффект.\nПри броске, заклинатель колдует на себе или объект, а не на оппонентов","second_stage_condition":"Зрительный контакт\nОбъект должен слышать колдующего\nРаботает только на разумных существ\nТаргетное заклинание","third_stage_condition":"Зрительная/телесная связь с объектом\nТаргетное заклинание\nВременный эффект","fourth_stage_condition":"Зрительный контакт\nОбъект должен слышать колдующего\nВозможен непредсказуемый эффект\nДействует только на разумных существ\nНе чаще одного использования за сессию"},{"id":26,"name":"Обман","attributes":"Искусство + Королевство + Обман +Право рождения/Иной бонус + Сокровище/Снаряжение","description":"Обман отвечает за искажение чужого восприятия и даёт возможность контролировать чужой разум. Обман требует прямого контакта - объект заклинания обязательно должен видеть или слышать колдующего. Обман работает только на одну цель.","type":3,"first_stage_name":"И снова Опиум","first_stage_description":"Позволяет исказить сенсорное восприятие объекта. Эффект работает только в режиме наложения: нельзя создать шум в тишине или заставить слепого видеть. Не наносит урона, но может заставить заклинаемого случайно причинить себе вред из-за нарушения восприятия мира. Также может быть использовано для отвода глаз от заклинателя, либо от какого бы то ни было объекта.","second_stage_name":"MIB","second_stage_description":"Заклинатель может стирать или похищать части воспоминаний и убеждений, или же производить точечное удаление воспоминаний. К примеру, он может уничтожить только воспоминание о том мгновении, когда объект колдовства врезался в него, следуя вниз по улице. Можно создать иллюзорное ложное воспоминание взамен стертого, либо оставить пустое пространство.","third_stage_name":"Клиническая Психотерапия","third_stage_description":"Даёт контроль над эмоциями жертвы. При наличии опоры на реальные чувства/воспоминания объекта, сложность колдовства снижается. Также, при помощи данного заклинания, можно вернуть/восстановить утраченные/померкшие воспоминания.","fourth_stage_name":"Манипулятивный Абьюз","fourth_stage_description":"При помощи этой магии, заклинатель может внести в характер объекта своего колдовства настолько большие изменения, что тот станет другой личностью. Также, при желании, колдующий может полностью подчинить объект своей воле. Заклинание может воздействовать только на одну цель.","created_at":"2023-10-05T10:09:28.000000Z","updated_at":"2025-10-27T04:41:03.000000Z","deleted_at":null,"first_stage_condition":"Таргетное заклинание\nВременный эффект\nЗрительный/телесный контакт/аудиальный контакт.\nОбъект должен вас слышать\nЭффект наложения\nОбъект должен быть разумным","second_stage_condition":"Таргетное Заклинание\nЗрительный/телесный контакт\nОбъект должен вас слышать\nОбъект должен быть разумным","third_stage_condition":"Таргетное Заклинание\nЗрительный/телесный контакт\nОбъект должен вас слышать\nОбъект должен быть разумным","fourth_stage_condition":"Таргетное Заклинание\nЗрительный/телесный контакт\nОбъект должен вас слышать\nОбъект должен быть разумным\nВозможен непредсказуемый эффект\nНе чаще одного использования за сессию"},{"id":27,"name":"Пламя","attributes":"Искусство + Королевство + Нападение + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Еще миллион лет назад смертные открыли для себя притягательность и красоту огня. Феи играли с его прекрасной мощью гораздо дольше. Они могут контролировать блуждающие огоньки и создавать слуг, состоящих из живого пламени.","type":3,"first_stage_name":"Горячо-Холодно","first_stage_description":"Заклятие поиска цели, указывающее место нахождения нужного предмета/места/существа. Блуждающий огонёк может принять либо форму шара, либо окружить свечением объект поиска, либо проявиться каким-либо ещё образом, обозначая направление или местоположение цели. Это пламя не имеет повышенной температуры и не способно согреть или нанести урон. Число успехов определяет точность найденного пути.","second_stage_name":"Кулак Прометея","second_stage_description":"Это колдовство позволяет полностью окружить определенный неодушевленный объект пламенем. Это пламя не будет наносить какого-либо урона ни заклинателю, ни данном объекту, но будет воздействовать на все остальное извне. Данное колдовство очень часто используется для того, чтобы зажигать оружие, которое после этого наносит противникам ужасные раны. Число успехов определяет число ходов, которое будут работать чары.","third_stage_name":"Молот Ведьм","third_stage_description":"Это колдовство позволяет окружить объект всепожирающим огнем, который быстро поглощает его. Огонь является обычным пламенем сразу же после своего появления, обжигая и сжигая объект воздействия данного колдовства так же, как если бы это было обычное пламя. Так же оно наносит урон заклинателю, если тот попытается прикоснуться к нему. Число успехов свыше уровня объекта воздействия определяют кол-во летального урона.","fourth_stage_name":"Дитя Сопряжения","fourth_stage_description":"С помощью этого колдовства заклинатель может превратить что/кого угодно в живое пламя, сохранив при этом все присущие данному объекту качества и способности - кот останется котом, меч останется мечом, человек сможет двигаться и думать, и так далее.  Число успехов определяет кол-во ходов, которые держится заклинание.","created_at":"2023-10-05T10:11:44.000000Z","updated_at":"2025-10-27T04:41:36.000000Z","deleted_at":null,"first_stage_condition":"Не наносит урон\nВременный эффект\nМагическое пламя\nЗаклинатель должен точно знать, как выглядит и чем является искомый объект.","second_stage_condition":"Временный эффект\nМагическое пламя\nРаботает только на неодушевленные объекты.","third_stage_condition":"Таргетное заклинание\nВозможен непредсказуемы эффект","fourth_stage_condition":"Временный эффект\nМагическое пламя\nВозможен непредсказуемы эффект\nНе чаще одного использования за сессию"},{"id":28,"name":"Правление","attributes":"Искусство + Королевство + Манипулирование + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"В древние времена, Правители использовали Искусство Правления для того, чтобы регулярно навязывать свои благородные эдикты простолюдинам. Некоторые делают это и по сей день. Искусство Правления заставляет простолюдинов и аристократов, занимающих равное или более низкое положение, подчиняться приказам заклинателя. Искусство недоступно для изучения на старте игры. Только специалист в этом искусстве может поделится знаниями с другими.","type":3,"first_stage_name":"Огни Гондора","first_stage_description":"Заклинатель произносит воодушевляющую речь, убеждающую всех в зоне колдовства откликнуться на зов и прийти на помощь. Количество успеха определяет радиус колдовства.","second_stage_name":"Путь Блиновской","second_stage_description":"Заклинатель вызывает восторг, священный трепет или любое другое нужное чувство у окружающих, и может выглядеть в чужих глаза словно бог. Цель/цели не могут не повиноваться приказу колдующего, но смутно ощущают неестественность желания подчиниться. Число успехов определяет успешность и число подчинившихся чарам.","third_stage_name":"Смерть Медвежатника","third_stage_description":"Оберег не позволяет переступить порог или взять предмет, на который он наложен. Он может использоваться в качестве “волшебного замка”, пропуская только определенных людей/иных существ, и как защита от чужой магии. Сила Оберега зависит от числа успехов. Чтобы снять Оберег, помимо того, чтоб понять, что он есть, требуется выбросить большее число успехов чем то, на которое он был наложен, либо уровень того, кто его наложил.","fourth_stage_name":"МФО","fourth_stage_description":"Действует как принудительная клятва, неисполнение которой карается проклятием, либо как запрет, не дающий заклинаемому совершить то или иное действие. Невыполнимые Клятвы или Запреты (например, Запрет дышать) сразу же спадают со своих целей. Сила Запрета, Клятвы или Проклятия зависит количества выброшенных успехов.","created_at":"2023-10-05T10:19:33.000000Z","updated_at":"2023-10-05T10:19:48.000000Z","deleted_at":null,"first_stage_condition":"Необходимо, чтобы объекты колдовства Вас слышали\nЦель не может причинить умышленного вреда себе или окружающим\nДействует только на разумных существ\nВременный эффект","second_stage_condition":"Необходимо, чтобы объекты колдовства Вас слышали\nЦель не может причинить умышленного вреда себе\nДействует только на разумных существ\nВременный эффект","third_stage_condition":"Оберег является Правилом.","fourth_stage_condition":"Не может заставить причинить умышленный вред себе\nДействует только на разумных существ\nЗрительный/Телесный контакт\nЯвляется правилом\nНе чаще одного использования за сессию"},{"id":29,"name":"Предсказания","attributes":"Искусство + Королевство + Проницательность +Право рождения/Иной бонус + Сокровище/Снаряжение","description":"Позволяет пассивно взаимодействовать с Временем и Вероятностью. Искусство позволяет видеть прошлое, настоящее и вероятные итерации будущего.","type":3,"first_stage_name":"Взгляд Фиби","first_stage_description":"Позволяет заклинателю видеть прошлое объекта заклятия. Число успехов равно числу задаваемых вопросов и подробности ответов в зависимости от уровня объекта колдовства.","second_stage_name":"Глазок","second_stage_description":"Заклинатель может видеть и слышать через вещь, точное географическое местоположение, которой ему известно. При использовании предварительно зачарованного предмета, необязательно знать его местоположение. Число успехов определяет длительность действия.","third_stage_name":"Осуждение Фортуны","third_stage_description":"Даёт заклинателю создать бафф или дебафф на определенный Атрибут на ближайший ход. Количество успехов определяет силу действия эффекта.","fourth_stage_name":"Слепая Пряха","fourth_stage_description":"Это колдовство позволяет определить и изменить судьбу объекта таким образом, чтобы нужная заклинателю вероятность развития событий в существовании объекта стала главенствующей. Механизм Слепой Пряхи даёт заклинателю силу определить судьбу объекта заклятия, после чего выбрать из предложенных наиболее комфортный ему вариант или предложить свой. В последнем случае результат может оказаться непредсказуемым. Число успехов определяет масштабность изменений…","created_at":"2023-10-05T10:22:19.000000Z","updated_at":"2023-10-05T10:22:33.000000Z","deleted_at":null,"first_stage_condition":"Таргетное заклинание\nРаботает только на неодушевленные предметы\nТелесный контакт","second_stage_condition":"Таргетное заклинание\nРаботает только на неодушевленные предметы\nВременный эффект\nЗнание точного внешнего вида объекта\nЗаклинатель видит лишь настоящее","third_stage_condition":"Таргетное заклинание\nРаботает только на \"Живые\" объекты\nЗрительный/телесный контакт\nВременный эффект\nНельзя использовать на себя","fourth_stage_condition":"Таргетное заклинание\nРаботает только на NPC\nРаботает только на \"Живые\" объекты\nЗрительный/телесный контакт\nВозможен непредсказуемый эффект\nНе чаще одного использования за сессию\n(Возможен мастерский произвол. Автор текста настоятельно рекомендует не применять это заклинание)"},{"id":34,"name":"Презрение","attributes":"Искусство + Королевство + Храбрость + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"У аристократов есть Искусство Правление, которое помогает править и насаждать правила. Презрение - это его противоположность, чье назначение эти правила нарушать, подрывать авторитеты и тому подобное.\nНедоступно на старте","type":3,"first_stage_name":"Насмешка","first_stage_description":"Данное колдовство не даёт объекту заклинания соблюдать местные социальные нормы. Число успехов определяет число ходов, в которые будет действовать заклинание. Позволяет защищаться от Правления.","second_stage_name":"Запах Свободы","second_stage_description":"Данное колдовство позволяет не повиноваться чужой власти и полностью игнорировать чужой авторитет, а также подталкивать к неповиновению других. Объекты воздействия заклинания становятся невосприимчивыми к любым формам команд и приказов. Может быть использован в качестве нейтрализации эффектов первых точек Правления и иной магии, направленной на подчинение и повиновение. Число успехов определяет число ходов, в которые будут действовать чары. Можно использовать на себя и окружение.","third_stage_name":"Болотная Память","third_stage_description":"Данное колдовство заставляет объект(ы) своего воздействия поднимать бунт и восстание против кого-либо/чего-либо, вызывая вспышку агрессивного анархического разгула в толпе. Поведение подвергшихся воздействию заклятия не контролируемо для колдующего. Нейтрализует собой первые точки Правления и другую магию, призывающую к повиновению. Число успехов определяет число подвергшихся магии людей.","fourth_stage_name":"Адвокат Дьявола","fourth_stage_description":"Колдующий может убедить кого угодно в чём угодно, и объект заклинания будет считать это истиной в последней инстанции. Благодаря этому эффекту, заклинатель может разрывать магические клятвы и договоры, как свои, так и чужие, в том числе снимать Гейсы - магические запреты, наложенные Правлением. Каждые 3 успеха = ослаблению клятвы/договора.","created_at":"2023-10-05T10:38:11.000000Z","updated_at":"2023-10-05T11:06:33.000000Z","deleted_at":null,"first_stage_condition":"Колдовство действует только на заклинателя.\nРаботает только на разумных существ","second_stage_condition":"Зрительный/телесный/аудио контакт с объектом колдовства\nРаботает только на разумных существ","third_stage_condition":"Зрительный/телесный/аудио контакт с объектом колдовства\nРаботает только на разумных существ\nНепредсказуемый результат\nВременный эффект\nНе чаще одного использования за сессию","fourth_stage_condition":"Зрительный/телесный/аудио контакт с объектом колдовства\nТаргетное заклинание\nРаботает только на разумных существ\nНе чаще одного использования за сессию"},{"id":30,"name":"Ремесло Историй","attributes":"Искусство + Королевство + Харизма + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Главной составляющей данного Искусства или тех Банков, которые применяются для него, всегда должна выступать некая форма повествования. Это повествование может преподноситься в любом виде, начиная поэзией и заканчивая песнями, но, в любом случае, его присутствие является обязательным.","type":3,"first_stage_name":"Бита Арлекино","first_stage_description":"Позволяет заклинателю определить настроение публики и настроить её на нужный лад. Идея или эмоция должна быть достаточно простой для того, чтобы это можно было выразить в одном или двух словах, и не может представлять собой приказ. Заклинатель также не может воздействовать на реакцию публики.","second_stage_name":"Премьера Аватара","second_stage_description":"Заклинатель притягивает к себе обрывки чужих мыслей и может создать на их основе ряд визуальных и звуковых иллюзий, которые будут иллюстрировать рассказываемую заклинателем историю. Иллюзии, созданные таким образом, не могут тактильно взаимодействовать ни с чем и причинять вред, не обладают разумом, но могут запутать, деморализовать или наоборот воодушевить тех, кто из видит.","third_stage_name":"Болтливый Патронус","third_stage_description":"Слова могут ранить и защитить. Заклинатель начинает рассказ, и в сочетании с темой истории он создает вокруг себя из слов и образов либо щит, либо оружие. Колдовство действует только пока рассказчик говорит, как только он замолкает или сильно сбивается - эффект пропадает. Щитом можно так же накрывать других персонажей/объекты..","fourth_stage_name":"Настоящий Мальчик","fourth_stage_description":"Колдующий начинает рассказывать историю, и в процессе рассказа появляется материальная химера, способная стать полноценным живым существом и осознать себя. Некоторые утверждают, что именно так появился Пинокио.","created_at":"2023-10-05T10:24:34.000000Z","updated_at":"2023-10-05T10:24:43.000000Z","deleted_at":null,"first_stage_condition":"Объекты заклинания должны слышать Заклинателя\nРаботает только на разумных существ","second_stage_condition":"Не телесное\nОбъекты должны видеть/слышать Заклинателя\nРаботает только на разумных существ","third_stage_condition":"Обязателен лирический отыгрыш\nНевозможность совершить другое действие","fourth_stage_condition":"Возможен непредсказуемый результат\nНевозможность совершить другое действие\nНе чаще одного использования за сессию"},{"id":43,"name":"Среда Настроений","attributes":"Искусство + Королевство + Проницательность + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Искусство построенное на эмоциях. Умение позволяющее лучше чувствовать и понимать мир вокруг себя, а порой и заставить мир испытать ваше эмоциональное состояние на себе. Искусство обязательно к отыгрышу \"банка\".","type":3,"first_stage_name":"Эмоциональный интеллект","first_stage_description":"Колдовство дает возможность настроиться на собеседника и при успехе считать наполняющие его эмоции. От доминирующих в данный момент, до самых потаенных. Считав объект, заклинатель может выбрать одну эмоцию из имеющихся и либо усилить, либо ослабить ее. Сила эффекта. определяет успешностью броска.","second_stage_name":"У страха глаза велики","second_stage_description":"Заклинатель присматривается к объекту колдовства и может отыскать его главную фобию. При успехе, заклинатель может усилить чувство страха и тревоги у объекта вводя его буквально в панический ужас. Сила эффекта зависит от успешность броска.","third_stage_name":"Гневилион","third_stage_description":"Атакующая способность. Позволяет в ход подготовки вылить весь накопившийся гнев в следующий удар, который нанесете вы или ваша цель колдовства. Может быть использовано как \"бафф\". Удар нанесенный под эффектом Гневилиона полностью игнорирует материальную/физическую защиту цели.","fourth_stage_name":"Карнавал Эмоций.","fourth_stage_description":"В результате собственного эмоционального взрыва, заклинатель выпускает волну вокруг себя, которая охватывает окружающих и усиливает все эмоции, которые они испытывают в данный момент в десятки, а то и сотни раз. Подверженные этому эффекту, бросают абсолютно все свои дела полностью отдаваясь, свои чувствам. Результаты абсолютно не предсказуемы и могут иметь чудовищно разрушительные последствия. Дальность волны, сила усиления эмоций и длительность эффекта зависит от успешности броска.","created_at":"2024-05-04T05:13:03.000000Z","updated_at":"2024-05-04T05:13:03.000000Z","deleted_at":null,"first_stage_condition":"Заклинатель должен видеть объект.\nНе позволяет читать мысли.\nОбязателен отыгрыш банка.\nТаргетное Заклинание","second_stage_condition":"Зрительный контакт.\nТаргетное заклинание.\nОбязателен отыгрыш банка.","third_stage_condition":"Таргетное заклинание.\nЗаклинание подготовка.\nВы должны видеть цель, если это \"бафф\".\nЭффект накладывается на одушевленное существо, способное к атаке.\nОбязателен отыгрыш банка.","fourth_stage_condition":"Заклинание можно использовать не чаще одного раза за партию.\nВозможен непредсказуемый результат.\nЗаклинатель не выбирает конкретные цели воздействия.\nОбязателен отыгрыш банка."},{"id":31,"name":"Странствия","attributes":"Искусство + Королевство + Внимание + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Искусство Странствий является Искусством умелого путешествия.","type":3,"first_stage_name":"120+","first_stage_description":"Это колдовство позволяет заклинателю или какому-либо другому существу двигаться невообразимо быстро в течение непродолжительного времени. Другие воспринимают объект воздействия магии, как расплывающееся в воздухе пятно. Число успехов определяет дистанцию и/или число людей, на которых будет оказан эффект.","second_stage_name":"Бегущий по Ветру","second_stage_description":"Это колдовство позволяет объекту своего воздействия летать. При прямом контакте, персонаж может распространить эффект на другой объект, при этом масса того, что он собирается поднять с собой в воздух не важна. Число успехов определяет длительность полёта: 2 успеха = 1 ход. При колдовстве на несколько существ сложность броска повышается.","third_stage_name":"Дырокол","third_stage_description":"Даёт возможность заклинателю открыть портал в любое место, если он точно знает, где оно находится или как выглядит. Число успехов определяет точность и время существования портала. Если для пересечения разделяющего расстояния между заклинателем и целью есть магические преграды, то он должен “перекинуть” их уровень.","fourth_stage_name":"Прыг-Скок","fourth_stage_description":"С помощью этого искусства, персонаж может исчезать и появляться в любом месте, в которое он хочет попасть. Заклинатель должен знать, видеть (или прорицать) или хотя бы обладать чем-то, что связано с местом его назначения. Если заклинатель забывает об этом условии, то колдовство может подействовать непредсказуемо. Если для пересечения разделяющего расстояния между заклинателем и целью есть магические преграды, то он должен “перекинуть” их уровень. Работает только на заклинателя.","created_at":"2023-10-05T10:27:44.000000Z","updated_at":"2025-10-27T04:42:13.000000Z","deleted_at":null,"first_stage_condition":"Телесный контакт\nВременный эффект\nС каждой дополнительной целью увеличивается сложность броска","second_stage_condition":"Зрительный/телесный контакт\nВременный эффект\nС каждой дополнительной целью увеличивается сложность броска","third_stage_condition":"Точное представление места назначение в мельчайших подробностях.\nИногда результат может быть непредсказуемым","fourth_stage_condition":"Таргетное\nМожно использовать только на себя\nТочное представление места назначение в мельчайших последствиях.\nВозможен непредсказуемый эффект\nНе чаще одного использования за сессию"},{"id":46,"name":"Страсть Стали","attributes":"Искусство + Атрибут заявки + Нападение + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Долгие века, многие считали род Аверно самыми талантливыми мечниками, передающими свое ремесло от отца к сыну. Но чтобы быть лучшим воином, мало хорошо владеть оружием в мире колдовства.","type":3,"first_stage_name":"Наследие Эскалибура","first_stage_description":"Заклинатель настраивается на особенности предстоящей или текущей битвы и может перед боем или в процессе зачаровать свое оружие на устойчивость к определенной стихии. Длительность колдовства определяется успешностью броска. (Например: защититься от скованности движения рук с оружием в воде или бушующем ветре, дать ему устойчивость к огню и так далее)","second_stage_name":"Проклятие Пацифизма","second_stage_description":"Заклинатель видит слабину оружия оппонента и  может проклясть его оружие и все действия вашего противника будут совершаться с повышенной сложностью/помехой/и тем и другим в зависимости от успешности броска, лирической заявки и лирической составляющей.","third_stage_name":"Мечник Дикого Запада","third_stage_description":"Заклинатель зачаровывает клинок, становясь с ним одним целым, что значительно ускоряет его действия и движения, давая ему возможность совершить два действия в свой ход в боевой сцене. Длительность эффекта зависит от числа успехов.","fourth_stage_name":"Зов Аверно","fourth_stage_description":"Все услышавшие зов потомки рода Аверно приходят на помощь к заклинателю в призрачной форме и сражаются на его стороне. Не смотря на их призрачность, они наносят вполне ощутимый урон врагам. Успешность броска влияет на количество призраков, и длительность их присутствия в битве.","created_at":"2025-10-27T04:47:23.000000Z","updated_at":"2025-10-27T04:47:23.000000Z","deleted_at":null,"first_stage_condition":"Таргетное заклинание\nКолдовство работает только на неодушевленные предметы\nКолдовство работает только на оружие\nКолдовство имеет временный эффект\nКолдовство работает только на конкретно указанную стихию","second_stage_condition":"Таргетное заклинание\nКолдовство работает только на неодушевленные предметы\nКолдовство работает только на оружие\nКолдовство имеет временный эффект","third_stage_condition":"Таргетное заклинание\nКолдовство работает только на неодушевленные предметы\nКолдовство работает только на оружие\nКолдовство имеет временный эффект","fourth_stage_condition":"Требуется лирический отыгрыш\nКолдовство имеет временный эффект\nЗаклинатель не управляет действиями призраков при их появлении\nВозможен непредсказуемый эффект\nНе чаще одного использования за сессию"},{"id":32,"name":"Управление Небесами","attributes":"Искусство + Королевство + Манипулирование + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Редко встречающееся искусство управления погодой, чаще всего известное только подводным и воздушным обитателям. Однако, срабатывает оно не всегда – есть такие места, которые защищены от воздействия этого волшебства – например подводные глубины. Вся магия этого искусства строится на сочетании стихии воздуха и воды.","type":3,"first_stage_name":"Пафос Морганы","first_stage_description":"Это колдовство позволяет управлять облаками и призвать туманы. В зависимости от желания персонажа и количества успехов, выброшенных игроком, заклинатель может вызвать и лёгкий туман, который можно будет разогнать, и непроглядное тёмное облако, не позволяющее разглядеть ничего дальше расстояния вытянутой руки.","second_stage_name":"Танец с Бубном","second_stage_description":"Это колдовство позволяет призвать дождь. В зависимости от желания персонажа и количества успехов, выброшенных игроком, колдующий может вызвать как легкую морось, так и тропический ливень, смывающий всё на своём пути.","third_stage_name":"Месть Прелюбодея","third_stage_description":"Заклинатель может призывать гром и разряд молнии. В зависимости от пожелания колдующего и числа успехов, выброшенных игроком, заклинатель может призвать как просто оглушающий звуком и светом удар молнии, как и мощный электрический разряд, способный покалечить или убить","fourth_stage_name":"Тайник Дейви Джонса","fourth_stage_description":"Заклинатель может управлять ветром и вызывать штормы и бури на море. В зависимости от цели колдующего и числа успехов, выброшенных игроком, заклинатель может призвать как направленный лёгкий порыв ветра, так и вызвать бурю и шквальный ветер. Призываемые этим колдовством шторма настолько мощные, что могут выйти из под контроля создателя.","created_at":"2023-10-05T10:33:38.000000Z","updated_at":"2023-10-05T10:33:38.000000Z","deleted_at":null,"first_stage_condition":"Возможен непредсказуемый эффект","second_stage_condition":"Возможен непредсказуемый эффект\nТолько в открытом пространстве","third_stage_condition":"Возможен непредсказуемый эффект\nТолько в открытом пространстве","fourth_stage_condition":"Возможен непредсказуемы эффект\nДействует только в водной среде\nНе чаще одного использования за сессию"},{"id":33,"name":"Фокусы","attributes":"Искусство + Королевство + Ловкость + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Искусство ловкости рук и иллюзий. Позволяет создавать материальные иллюзии и воздействовать на реальный мир, в отличие от Обмана.","type":3,"first_stage_name":"Акцио","first_stage_description":"Притягивание позволяет перемещать материальные вещи/существ с помощью телекинеза. С помощью этого колдовства они могут двигать, вращать, метать, поднимать и разбивать предметы, и чинить всевозможные препятствия.","second_stage_name":"Три карты Монте","second_stage_description":"Это колдовство создает дубликат предмета, которое колдующий может видеть или к которому может прикасаться. Копия обладает всеми особенностями данного объекта, которые можно увидеть и ощутить. Тем не менее, колдовство является только внешним, так как внутренние качества объекта с помощью этой магии не передаются. Срок существования иллюзии и его достоверность определяются кол-вом успехов. Работает только на неживые объекты.","third_stage_name":"Следи за Дамой","third_stage_description":"Заклинатель может мгновенно перемещать вещи из одного места в другое. Действует это колдовство только в том случае, если персонаж точно знает, где находится предмет, либо видел его в течение нескольких последних минут, либо смотрит непосредственно на предмет в момент колдовства.","fourth_stage_name":"Ширма","fourth_stage_description":"Это колдовство представляет собой высшую степень создания иллюзий. Если Три Карты Монте способно создавать только неподвижную копию, то Ширма создают полноценные Призрачные Тени. Призрачная Тень - это управляемая материальная субстанция, способная выйти из подчинения заклинателя и уйти жить самостоятельно","created_at":"2023-10-05T10:35:32.000000Z","updated_at":"2025-10-27T04:42:51.000000Z","deleted_at":null,"first_stage_condition":"Таргетное заклинание\nЗрительный контакт\nРаботает только на неодушевленные объекты","second_stage_condition":"Зрительный/телесный контакт\nРаботает только на неживые объекты\nТаргетное заклинание\nИллюзии будут осязаемы, но не могут нанести урона, рассыпаясь при столкновении. Созданные иллюзорные предметы не двигаются, без участия внешней силы или другого колдовства","third_stage_condition":"Обязательное точное знание местоположение предмета\nТолько на неодушевлённые объекты\nТаргетное колдовство","fourth_stage_condition":"Таргетное колдовство\nМожет быть только одна иллюзия за применение\nВозможен непредсказуемый эффект\nНе чаще одного использования за сессию"},{"id":44,"name":"Чудеса Отражений","attributes":"Искусство + Королевство + Культура + Право Рождения/Иной бонус + Сокровище/Снаряжение","description":"Давно забытое и по мнению многих утраченная Магия Зеркал","type":3,"first_stage_name":"Поиск Истины","first_stage_description":"Заклинатель может почувствовать, где находятся ближайшие окружающие его Зеркала в определенной локации. Так же он может войти в транс и посмотреть, что в данный момент отражает Зеркало, на которое он настроен. Кроме того, владеющий этим Искусством имеет особую связь с зеркалами, и может определить магические свойства Зеркала. Дальность радиуса поиска Зеркал а так же длительность просмотра и успешность определения магических свойств, зависит от успешности броска. Заклинателя в этот момент не могут увидеть.","second_stage_name":"Свет мой Зеркальце","second_stage_description":"Колдовство помогает узнать, многие чужие секреты. Заклинатель обращается к отражениям внутри любого Зеркала. Если они являются, то могут рассказать Заклинателю свидетелями чего они стали в рамках лирического диалога. Успешность броска определяет длительность нахождения отражения у поверхности.","third_stage_name":"Пути Семирамиды","third_stage_description":"Заклинание позволяет использовать Зеркала обычные или зачарованные, в качестве дверей для перемещения. Заклинатель может зайти в одно зеркало и выйти из другого. Число успехов отражает стабильность прохода и возможность провести с собой кого то еще.","fourth_stage_name":"И свитер такой же синий.","fourth_stage_description":"Самые темный глубины Зеркал отражений могут призвать не просто призрачный осколок, а полноценное Отражение из Сияющего Пространства. Он может использовать его как советника или же выпустить его на волю, дав какую то цель. Допельгангер будет действовать на свое усмотрение, пока не выполнит Поставленную задачу. Что произойдет после выполнения цели неизвестно.","created_at":"2024-05-04T05:15:12.000000Z","updated_at":"2024-05-04T05:15:12.000000Z","deleted_at":null,"first_stage_condition":"Для определения магических свойств Зеркала нужен Телесный Контакт.\nЕсли заклинатель хочет посмотреть через зеркало, находясь в Сияющем Пространстве, то местонахождение Зеркала не имеет значение.\nВо время транса заклинатель не может совершать других действий.","second_stage_condition":"Для колдовства необходимо иметь Зеркало.\nЗаклинатель должен знать чье отражение он призывает ( либо может предоставить это на милость Фортуны)\nОтражение может поведать лишь о том, что оно видело через Зеркало, которое послужило объектом колдовства.\nОтражения не обязательно говорят правду.\nТелесный контакт с зеркалом.","third_stage_condition":"Для колдовства необходимо два Зеркала.\nЗаклинатель должен знать, где находится каждое зеркало и что оно отражает.\nНе позволяет проникнуть в Сияющее Пространство.","fourth_stage_condition":"Не чаще одного раза за партию ( а лучше вообще не надо).\nДопельгангер может извратить вашу цель в своей голове и выполнить ее не так, как вы планировали ( ну правда не надо).\nИмеет непредсказуемые последствия ( Я серьезно. Это хреновая идея).\nНеобходимо иметь зеркало, в котором хотя бы раз отражался тот, чьего Допельгангера вы хотите призвать. ( ну раз уж вы решили...)"}]} as const

